/* LLM Atlas — concept registry for hover definitions and the glossary.
   id: { t: 中文名, en: English, d: 一两句定义（数学用 \( \)，会被 KaTeX 渲染）, at: 'slug#anchor' (where it is defined) }
   Mark the defining occurrence with <dfn data-t="id">…</dfn> and later uses with <span class="term" data-t="id">…</span>.
   If the defining chapter has not been rewritten yet (no <dfn> there), clicks go to the glossary entry instead. */
window.ATLAS_TERMS = {
  // ---- basics used across chapters
  'cross-entropy': { t: '交叉熵', en: 'cross-entropy', d: String.raw`\(-\log p(\text{正确答案})\)：模型给正确答案的概率越高，交叉熵越小。语言模型预训练和 SFT 的损失函数。`, at: 'generation#g0-loss' },
  'exposure-bias': { t: '暴露偏差', en: 'exposure bias', d: '训练时模型总看到正确的前文，推理时却要接着自己写的、可能出错的前文往下写；它从没练过“写错之后怎么办”。', at: 'rl#why' },

  // ---- tokens.html
  oov: { t: '未登录词', en: 'out-of-vocabulary (OOV)', d: '词表里没有的词。按词分词时只能把它替换成一个“未知”符号，信息就丢了。子词和字节级分词消除了这个问题。', at: 'tokens#why' },
  subword: { t: '子词分词', en: 'subword tokenization', d: '常见片段整体作为一个 token，罕见词拆成几块，最坏退回单个字节。在序列长度和词表大小之间折中。', at: 'tokens#why' },
  token: { t: 'token', en: 'token', d: '分词切出的基本单位，可能是一个词、半个词、几个字或一个字节。每个 token 有一个整数编号。', at: 'tokens#why' },
  vocab: { t: '词表', en: 'vocabulary', d: String.raw`所有可能的 token 的集合，大小记作 \(V\)，2026 年的大模型通常在 10 万到 26 万之间。`, at: 'tokens#why' },
  fertility: { t: '切分率（fertility）', en: 'fertility', d: '平均每个词（或字）被切成几个 token。越低越省；同一个分词器对不同语言差别很大。', at: 'tokens#why' },
  bpe: { t: 'BPE', en: 'byte pair encoding', d: '从单个字符或字节开始，反复把语料中出现次数最多的相邻一对合并成新 token，直到词表达到目标大小。本质是贪心压缩。', at: 'tokens#zero-merge' },
  utf8: { t: 'UTF-8', en: 'UTF-8', d: '最常用的文本编码：ASCII 字符占 1 个字节，大部分欧洲文字 2 个，汉字 3 个，emoji 4 个。', at: 'tokens#bytes' },
  'byte-bpe': { t: '字节级 BPE', en: 'byte-level BPE', d: '以 256 种字节为起始符号做 BPE（GPT-2 起）。任何文本都能编码，没有未登录词；代价是非拉丁文字可能占多个 token。', at: 'tokens#bytes' },
  'unigram-lm': { t: 'Unigram 分词', en: 'unigram language model tokenization', d: String.raw`给每个 token 一个概率 \(p(x)\)，在一句话所有可能的切法里选 \(\sum_i \log p(x_i)\) 最大的那种（Viterbi 算法）。`, at: 'tokens#unigram' },
  'subword-reg': { t: '子词正则化', en: 'subword regularization', d: '训练时不总用最优切法，而按概率随机采样一种切法，让模型见过同一个词的多种切法，更稳健。', at: 'tokens#unigram' },
  'special-token': { t: '特殊 token', en: 'special token', d: '不对应普通文字的控制符号：文本开始 / 结束、对话角色、思维链边界、工具调用、图像占位等。', at: 'tokens#special' },
  'chat-template': { t: '聊天模板', en: 'chat template', d: '把一段对话按固定格式插入特殊 token（系统、用户、助手、工具……）后拼成一条序列。用错模板，模型表现会明显下降。', at: 'tokens#special' },
  'embedding-matrix': { t: '嵌入矩阵', en: 'embedding matrix', d: String.raw`形状 \(V\times d\) 的参数矩阵 \(E\)，第 \(i\) 行是编号为 \(i\) 的 token 的向量。和其它参数一起训练。`, at: 'tokens#zero-lookup' },
  embedding: { t: '嵌入（向量）', en: 'embedding', d: String.raw`一个 token 对应的 \(d\) 维向量，即嵌入矩阵的一行。训练后意思相近的 token，嵌入的方向也相近。`, at: 'tokens#zero-lookup' },
  'one-hot': { t: '独热向量', en: 'one-hot vector', d: String.raw`长度为 \(V\)、只有第 \(i\) 位是 1、其余都是 0 的向量。用它乘嵌入矩阵，等于取出第 \(i\) 行。`, at: 'tokens#zero-lookup' },
  cosine: { t: '余弦相似度', en: 'cosine similarity', d: String.raw`\(\cos(\mathbf u,\mathbf v) = \frac{\mathbf u\cdot\mathbf v}{\|\mathbf u\|\|\mathbf v\|}\)，只看两个向量的方向是否一致，取值在 −1 到 1 之间。`, at: 'tokens#zero-cos' },
  distributional: { t: '分布假说', en: 'distributional hypothesis', d: '一个词的意思由它出现的上下文决定。出现在相似上下文里的词，意思相近。词向量和语言模型都建立在这个假设上。', at: 'tokens#meaning' },
  pmi: { t: '点互信息（PMI）', en: 'pointwise mutual information', d: String.raw`\(\mathrm{PMI}(w,c) = \log\frac{p(w,c)}{p(w)\,p(c)}\)：两个词一起出现的频率，比各自独立时偶然相遇的频率高多少倍（取对数）。`, at: 'tokens#meaning' },
  logit: { t: 'logit', en: 'logit', d: String.raw`模型对每个候选 token 给出的未归一化分数 \(z_i\)。经过 softmax 才变成概率；所有 logit 同加一个常数，概率不变。`, at: 'tokens#output' },
  softmax: { t: 'softmax', en: 'softmax', d: String.raw`把一组任意实数分数 \(z_1,\dots,z_n\) 变成和为 1 的概率：\(p_i = e^{z_i} / \sum_j e^{z_j}\)。分数越高，概率越大；所有分数同加一个常数，结果不变。`, at: 'tokens#output' },
  'tied-embeddings': { t: '共享嵌入', en: 'tied embeddings', d: String.raw`让输出矩阵直接复用输入的嵌入矩阵（\(W_U = E\)），省下 \(Vd\) 个参数。小模型常用，大模型通常不共享。`, at: 'tokens#output' },

  // ---- reinforcement learning (rl.html)
  agent: { t: '智能体（RL）', en: 'agent', d: '做决定的一方。在语言模型的 RL 里，智能体就是模型本身。', at: 'rl#rl0-game' },
  environment: { t: '环境', en: 'environment', d: '接收智能体的动作、给出新状态和奖励的一方：按钮游戏里的按钮，数学题的判分程序，智能体任务里的沙盒。', at: 'rl#rl0-game' },
  policy: { t: '策略', en: 'policy', d: String.raw`智能体在每个状态下选择各个动作的概率分布 \(\pi_\theta(a\mid s)\)。语言模型给出下一个 token 的分布，它本身就是策略。`, at: 'rl#rl0-game' },
  reward: { t: '奖励', en: 'reward', d: String.raw`环境在某个动作或一局结束之后给出的分数 \(R\)。RL 只靠它来学习，没有标准答案。`, at: 'rl#rl0-game' },
  objective: { t: '期望奖励', en: 'expected reward', d: String.raw`\(J(\theta) = \mathbb E_{a\sim\pi_\theta}[R(a)]\)：按当前策略行动，平均能拿多少分。RL 的目标是让它最大。`, at: 'rl#rl0-game' },
  'policy-gradient': { t: '策略梯度', en: 'policy gradient', d: String.raw`\(\nabla_\theta J = \mathbb E\big[R\,\nabla_\theta\log\pi_\theta(a)\big]\)：采样一个动作，按它的得分把它的对数概率往上推。最早的形式叫 REINFORCE（1992）。`, at: 'rl#rl0-pg' },
  baseline: { t: '基线', en: 'baseline', d: String.raw`从奖励里减去的参考值 \(b\)，通常取平均得分。它不改变梯度的期望，但能大幅降低梯度估计的方差。`, at: 'rl#rl0-baseline' },
  advantage: { t: '优势', en: 'advantage', d: String.raw`\(A = R - b\)：这个动作（或这条回答）比平均水平好多少。正的就加强，负的就削弱。`, at: 'rl#rl0-baseline' },
  'gradient-variance': { t: '梯度估计的方差', en: 'variance of the gradient estimate', d: '用少量样本估计梯度时，每次估计结果的波动大小。方差大，训练就慢、不稳定。', at: 'rl#rl0-baseline' },
  entropy: { t: '熵', en: 'entropy', d: String.raw`分布的平均信息量 \(H(p) = -\sum_x p(x)\log p(x)\)：完全均匀时最大，只剩一个结果时为 0。语言模型里衡量下一个 token 有多不确定；强化学习里衡量策略还有多随机。`, at: 'generation#g0-info' },
  exploration: { t: '探索与利用', en: 'exploration vs. exploitation', d: '利用：选目前看来最好的动作；探索：尝试其它动作，看会不会更好。只利用不探索，可能永远发现不了更好的选择。', at: 'rl#rl0-entropy' },
  'entropy-collapse': { t: '熵塌缩', en: 'entropy collapse', d: '训练中策略的熵过早地降到接近 0：模型几乎总做同一种选择，停止探索。', at: 'rl#rl0-entropy' },
  state: { t: '状态', en: 'state', d: String.raw`智能体做决定时能看到的全部信息 \(s_t\)。语言模型里是题目加上已经生成的前缀。`, at: 'rl#rl0-steps' },
  trajectory: { t: '轨迹', en: 'trajectory / episode', d: '从开始到结束的一整局：状态、动作、奖励交替组成的序列。语言模型里就是一条完整的回答。', at: 'rl#rl0-steps' },
  rollout: { t: '采样（rollout）', en: 'rollout', d: '让当前策略实际跑一局、生成轨迹。在语言模型里就是让模型生成回答，通常占 RL 算力的一半左右。', at: 'rl#rl0-steps' },
  return: { t: '回报', en: 'return', d: String.raw`从第 \(t\) 步到结束拿到的奖励之和 \(G_t = \sum_{k\ge t}\gamma^{k-t} r_k\)。语言模型通常只在最后给一次奖励、取 \(\gamma = 1\)，回报就是那一个分数。`, at: 'rl#rl0-steps' },
  credit: { t: '功劳分配', en: 'credit assignment', d: '最后的奖励该归功于哪些动作。一盘棋走了 60 步才分胜负，哪几步是好棋？', at: 'rl#rl0-steps' },
  value: { t: '价值函数', en: 'value function', d: String.raw`\(V(s)\)：从状态 \(s\) 出发、按当前策略继续行动，平均能拿多少回报。\(Q(s,a)\) 则是先做动作 \(a\) 再继续的平均回报。`, at: 'rl#rl0-steps' },
  critic: { t: '价值网络（critic）', en: 'critic', d: String.raw`学习价值函数 \(V(s)\) 的神经网络，用来给每一步估计优势。和它配合、负责选动作的策略叫 actor。`, at: 'rl#rl0-steps' },
  gae: { t: 'GAE', en: 'generalized advantage estimation', d: String.raw`用价值网络逐步估计优势：TD 误差 \(\delta_t = r_t + \gamma V(s_{t+1}) - V(s_t)\) 按 \((\gamma\lambda)^l\) 加权累加，\(\lambda\) 在偏差和方差之间折中。`, at: 'rl#rl0-steps' },
  'on-policy': { t: '同策略', en: 'on-policy', d: '用当前策略自己采的样本来更新当前策略。策略梯度公式默认就是同策略。', at: 'rl#rl0-offpolicy' },
  'off-policy': { t: '离策略', en: 'off-policy', d: '用另一个策略（比如几步之前的旧策略）采的样本来更新当前策略，需要重要性采样来修正。', at: 'rl#rl0-offpolicy' },
  'importance-sampling': { t: '重要性采样', en: 'importance sampling', d: String.raw`用分布 \(q\) 的样本估计分布 \(p\) 下的期望：每个样本乘上权重 \(p(x)/q(x)\)。两个分布差得越远，权重越不均匀，估计越不稳定。`, at: 'rl#rl0-offpolicy' },
  kl: { t: 'KL 散度', en: 'Kullback–Leibler divergence', d: String.raw`\(D_{\text{KL}}(p\,\|\,q) = \sum_x p(x)\log\frac{p(x)}{q(x)}\)，衡量两个分布差多少：恒 \(\ge 0\)，两者相同时为 0，不对称。`, at: 'rl#rl0-offpolicy' },
  'trust-region': { t: '信任域', en: 'trust region', d: '只在离当前策略不远（KL 小）的范围内更新，因为离得越远，用旧样本估计的梯度越不可信。TRPO、PPO 的核心思想。', at: 'rl#rl0-offpolicy' },
  ess: { t: '有效样本量', en: 'effective sample size (ESS)', d: String.raw`\(\text{ESS} = (\sum_i w_i)^2 / \sum_i w_i^2\)：一批带权重的样本相当于多少个等权样本。权重越不均匀，ESS 越小。`, at: 'rl#rl0-offpolicy' },
  ratio: { t: '重要性比率', en: 'importance ratio', d: String.raw`\(r_t = \pi_\theta(y_t) / \pi_{\text{old}}(y_t)\)：当前策略和采样时的策略给同一个 token 的概率之比。`, at: 'rl#ppo' },
  'ppo-clip': { t: '裁剪（PPO）', en: 'clipping', d: String.raw`把重要性比率限制在 \([1-\epsilon,\, 1+\epsilon]\) 内：一个 token 已经被往对的方向推够了，就不再给它梯度。`, at: 'rl#ppo' },
  ppo: { t: 'PPO', en: 'proximal policy optimization', d: '2017 年的策略梯度算法：重要性采样 + 裁剪 + 价值网络。此后七年 RL 微调的默认算法。', at: 'rl#ppo' },
  rlhf: { t: 'RLHF', en: 'reinforcement learning from human feedback', d: '用人类偏好训练奖励模型，再用 RL 优化语言模型。InstructGPT 和 ChatGPT 的做法。', at: 'sft#z-kl' },
  grpo: { t: 'GRPO', en: 'group relative policy optimization', d: String.raw`每道题采样一组 \(G\) 个回答，用组内平均奖励当基线，去掉价值网络。DeepSeekMath（2024）提出，R1 用它训练。`, at: 'rl#grpo' },
  rlvr: { t: 'RLVR', en: 'RL with verifiable rewards', d: '只在能自动判断对错的任务上做 RL：数学比对答案、代码跑测试、智能体检查终态。', at: 'rl#reward' },
  'reward-hacking': { t: '钻奖励空子', en: 'reward hacking', d: '模型找到了提高奖励、却不真正完成任务的办法，比如写得更长讨好评分模型、修改单元测试。', at: 'rl#reward' },
  passk: { t: 'pass@k', en: 'pass@k', d: String.raw`每道题采样 \(k\) 次，至少一次答对就算解出。\(k = 1\) 看“一次做对”，\(k\) 很大时看能力的边界。`, at: 'rl#debate' },

  // ---- attention (attention.html)
  rnn: { t: '循环神经网络', en: 'recurrent neural network (RNN)', d: String.raw`从左到右逐个读 token，每一步用当前 token 更新一个固定大小的隐藏状态：\(\mathbf h_t = \tanh(W\mathbf h_{t-1} + U\mathbf x_t)\)。LSTM、GRU 是加了门控的改进版。`, at: 'attention#before' },
  'vanishing-grad': { t: '梯度消失', en: 'vanishing gradient', d: '梯度要经过很多次连乘才能传到前面的层或前面的时间步；每次乘的因子小于 1 时，梯度指数级衰减，前面的部分几乎学不到东西。', at: 'attention#before' },
  'attention-mech': { t: '注意力', en: 'attention', d: '对每个位置算一个相关度，按相关度把各位置的信息加权平均。2014 年用于机器翻译，2017 年成为 Transformer 的核心。', at: 'attention#before' },
  'self-attention': { t: '自注意力', en: 'self-attention', d: '序列内部的注意力：query、key、value 都来自同一个序列，每个位置去看同一序列中的其它位置。', at: 'attention#before' },
  'attn-query': { t: 'query（查询）', en: 'query', d: String.raw`\(\mathbf q = \mathbf x W_Q\)：一个位置“在找什么样的信息”。和每个 key 做点积，得到相关度分数。`, at: 'attention#qkv' },
  'attn-key': { t: 'key（键）', en: 'key', d: String.raw`\(\mathbf k = \mathbf x W_K\)：一个位置“有什么样的信息”，供 query 匹配。`, at: 'attention#qkv' },
  'attn-value': { t: 'value（值）', en: 'value', d: String.raw`\(\mathbf v = \mathbf x W_V\)：一个位置被关注时“交出去的内容”。注意力输出是 value 的加权平均。`, at: 'attention#qkv' },
  'multi-head': { t: '多头注意力', en: 'multi-head attention', d: String.raw`用 \(h\) 套各自的投影，把输入 \(\mathbf x\) 投到 \(h\) 个 \(d_h\) 维（通常 \(d_h=d/h\)）的子空间，各做一次注意力，结果拼接后乘 \(W_O\)。每个头有自己的一次 softmax，所以能同时看不同的地方；总参数量和单个 \(d\) 维的头相同。`, at: 'attention#multihead' },
  'causal-mask': { t: '因果掩码', en: 'causal mask', d: String.raw`softmax 之前把“后面位置”的分数设为 \(-\infty\)，使每个位置只能看到自己和前面的 token。生成模型必须用它。`, at: 'attention#causal' },
  'cross-attention': { t: '交叉注意力', en: 'cross-attention', d: 'query 来自一个序列，key 和 value 来自另一个序列。翻译模型的解码器用它读原句，文生图模型用它读提示词。', at: 'attention#causal' },
  'induction-head': { t: '归纳头', en: 'induction head', d: '一种两层配合的注意力电路：看到 A 时，找到上文中 A 之后出现过的 B，把它复制为预测。与上下文学习能力的出现同步形成。', at: 'attention#induction' },
  icl: { t: '上下文学习', en: 'in-context learning (ICL)', d: '不更新参数，只在提示词里给几个示例，模型就能完成新任务。few-shot 提示依赖这种能力。', at: 'attention#induction' },
  'attention-sink': { t: '注意力汇', en: 'attention sink', d: '很多注意力头把大量权重放在第一个 token 上。softmax 的权重和必须为 1，没什么要看时多余的权重要有个去处。', at: 'attention#sink' },

  // ---- transformer (transformer.html)
  'decoder-only': { t: '只有解码器', en: 'decoder-only', d: '只用带因果掩码的自注意力、任务统一为“预测下一个 token”的 Transformer。GPT 系列及几乎所有当今大语言模型都是这种结构。', at: 'transformer#why' },
  block: { t: 'Transformer 块', en: 'Transformer block', d: String.raw`模型重复堆叠的基本单元：\(\mathbf h = \mathbf x + \operatorname{Attn}(\operatorname{Norm}(\mathbf x))\)，\(\mathbf x' = \mathbf h + \operatorname{MLP}(\operatorname{Norm}(\mathbf h))\)。`, at: 'transformer#why' },
  residual: { t: '残差连接', en: 'residual connection', d: String.raw`子层只输出一个修改量，加回输入：\(\mathbf x_{l+1} = \mathbf x_l + F(\mathbf x_l)\)。反向传播时梯度有一条不衰减的直通路径。`, at: 'transformer#residual' },
  'residual-stream': { t: '残差流', en: 'residual stream', d: '每个位置上贯穿所有层的那条向量。注意力和 MLP 从中读取信息、把结果加回去，所有层共享这条“总线”。', at: 'transformer#residual' },
  ffn: { t: '前馈网络（MLP）', en: 'feed-forward network', d: String.raw`每个块的第二个子层，对每个位置独立计算：\(\phi(\mathbf xW_1)W_2\)，先升维到约 \(4d\)、过激活函数、再降回 \(d\)。约占每层参数的三分之二。`, at: 'transformer#mlp' },
  swiglu: { t: 'SwiGLU', en: 'SwiGLU', d: String.raw`带门控的 MLP：\((\operatorname{SiLU}(\mathbf xW_1)\odot \mathbf xW_3)\,W_2\)。三个矩阵，中间维度约 \(\tfrac83 d\)。2023 年起的标准。`, at: 'transformer#mlp' },
  layernorm: { t: '层归一化', en: 'LayerNorm', d: String.raw`对每个位置的向量减去均值、除以标准差，再乘可学习的系数：\(\mathbf g\odot(\mathbf x-\mu)/\sigma + \mathbf b\)。`, at: 'transformer#norm' },
  rmsnorm: { t: 'RMSNorm', en: 'RMSNorm', d: String.raw`只除以均方根的归一化：\(\mathbf g\odot\mathbf x/\sqrt{\tfrac1d\sum_i x_i^2}\)。比 LayerNorm 省，效果相当，是现在的标准。`, at: 'transformer#norm' },
  'pre-norm': { t: 'Pre-Norm', en: 'pre-normalization', d: String.raw`只对子层的输入做归一化，残差路径不经过归一化：\(\mathbf x + F(\operatorname{Norm}(\mathbf x))\)。训练稳定，但残差流会随层数变长。`, at: 'transformer#norm' },
  'perm-equiv': { t: '置换等变', en: 'permutation equivariance', d: '把输入的顺序打乱，输出只是同样地被打乱，数值不变。不带位置信息的注意力就是这样，因此分不清顺序。', at: 'transformer#position' },
  'pos-enc': { t: '位置编码', en: 'positional encoding', d: '向模型注入 token 顺序信息的方法：正弦编码、可学习的位置向量、相对位置偏置、RoPE 等。', at: 'transformer#position' },
  rope: { t: 'RoPE', en: 'rotary position embedding', d: String.raw`按位置旋转 query 和 key：第 \(i\) 个二维平面转 \(m\theta_i\)，\(\theta_i = b^{-2i/d}\)。旋转后点积只依赖相对位置 \(n-m\)。`, at: 'transformer#position' },
  flops: { t: 'FLOPs', en: 'floating-point operations', d: String.raw`浮点运算次数，一次乘加记 2 次。稠密模型前向每 token 约 \(2N\)，训练约 \(6N\)（\(N\) 为参数量）。注意与表示“每秒运算次数”的 FLOPS 区分。`, at: 'transformer#params' },

  // ---- generation (generation.html)
  autoregressive: { t: '自回归', en: 'autoregressive', d: String.raw`按 \(p(x_1,\dots,x_T) = \prod_t p(x_t\mid x_{<t})\) 从左到右逐个生成：每一步的输出成为下一步的输入。`, at: 'generation#ar' },
  'teacher-forcing': { t: 'teacher forcing', en: 'teacher forcing', d: '训练时每一步都输入真实的前缀，而不是模型自己生成的前缀。配合因果掩码，所有位置可以并行计算损失。', at: 'generation#ar' },
  perplexity: { t: '困惑度', en: 'perplexity', d: String.raw`交叉熵损失的指数 \(\exp(\mathcal L)\)：模型平均在多少个等可能的候选里犹豫。依赖分词方式，不同词表的模型不可直接比较。`, at: 'generation#g0-loss' },
  bpb: { t: '每字节比特数', en: 'bits per byte', d: String.raw`总损失换算成比特（除以 \(\ln 2\)）再除以文本的 UTF-8 字节数。与分词无关，可跨模型比较，也等于模型压缩这段文本的码长。`, at: 'generation#ppl' },
  ngram: { t: 'n-gram 模型', en: 'n-gram model', d: String.raw`假设下一个 token 只依赖前 \(n-1\) 个，用语料中的出现次数估计条件概率。受数据稀疏限制，上下文很短。`, at: 'generation#ngram' },
  greedy: { t: '贪心解码', en: 'greedy decoding', d: '每一步都选概率最高的 token。确定，但开放式生成时容易陷入重复。', at: 'generation#g0-sample' },
  temperature: { t: '温度', en: 'temperature', d: String.raw`softmax 前把 logit 除以 \(T\)：\(p_i\propto e^{z_i/T}\)。\(T<1\) 分布变尖，\(T>1\) 变平，\(T\to 0\) 即贪心。`, at: 'generation#g0-sample' },
  'top-k': { t: 'top-k 采样', en: 'top-k sampling', d: String.raw`只在概率最高的 \(k\) 个 token 中重新归一化后采样。`, at: 'generation#decode' },
  'top-p': { t: 'top-p 采样', en: 'nucleus / top-p sampling', d: String.raw`按概率从高到低累加，保留累计达到 \(p\) 的最小头部集合，在其中采样。候选数随分布形状自动伸缩。`, at: 'generation#decode' },
  'min-p': { t: 'min-p 采样', en: 'min-p sampling', d: String.raw`只保留概率不低于 \(p_{\min}\times p_{\max}\) 的 token。宣称在高温下更稳，但其优势在 2025 年的复查中受到质疑。`, at: 'generation#decode' },
  'beam-search': { t: '束搜索', en: 'beam search', d: String.raw`同时保留 \(b\) 条得分最高的部分序列，逐步扩展。适合翻译等答案确定的任务，开放式生成中会导致空洞重复。`, at: 'generation#degen' },
  'constrained-decoding': { t: '约束解码', en: 'constrained decoding', d: '每一步按语法（JSON Schema、正则等）屏蔽不合法的 token，保证输出一定能被解析。结构化输出和工具调用依赖它。', at: 'generation#constrained' },
  mtp: { t: '多 token 预测', en: 'multi-token prediction (MTP)', d: '训练时额外预测后面第 2、3 个 token，训练信号更密；推理时这些额外预测可作为投机解码的草稿。DeepSeek-V3 采用。', at: 'generation#beyond' },
  'diffusion-lm': { t: '扩散语言模型', en: 'diffusion language model', d: '从全部被遮住的序列出发，多轮并行地填写和修改各位置，而不是从左到右逐个生成。代表：LLaDA、Gemini Diffusion、Mercury。', at: 'generation#dlm' },
  calibration: { t: '校准', en: 'calibration', d: '模型给出的概率与实际正确率是否一致：说 70% 有把握的答案，是否大约 70% 是对的。后训练常使模型过度自信。', at: 'generation#myths' },

  // ---- data (data.html)
  'common-crawl': { t: 'Common Crawl', en: 'Common Crawl', d: '非营利组织自 2008 年起定期抓取全网并免费公开的网页存档，每次抓取数十亿网页，是绝大多数预训练语料的来源。', at: 'data#why' },
  jaccard: { t: 'Jaccard 相似度', en: 'Jaccard similarity', d: String.raw`两个集合交集大小除以并集大小：\(J(A,B) = |A\cap B|/|A\cup B|\)，0 到 1。去重时 A、B 是两篇文档的片段集合。`, at: 'data#dedup' },
  minhash: { t: 'MinHash', en: 'MinHash', d: String.raw`用随机哈希函数取集合的最小哈希值作为签名：两个集合最小值相等的概率恰好是它们的 Jaccard 相似度。配合 LSH 分桶，可在数十亿文档中快速找到近似重复。`, at: 'data#dedup' },
  'quality-classifier': { t: '质量分类器', en: 'quality classifier', d: '给每篇文档打分、只保留高分文档的小模型。正例可以是“像维基百科”“像优质问答”，或由大模型按教育价值标注（FineWeb-Edu）。', at: 'data#quality' },
  'data-mixture': { t: '数据配比', en: 'data mixture', d: '网页、代码、数学、论文、书籍、多语言等各类数据在训练中所占的比例。通常在小模型上搜索后外推到大模型。', at: 'data#mixture' },
  'mid-training': { t: '中期训练（退火）', en: 'mid-training / annealing', d: '预训练末段学习率降到接近 0 时，换用质量最高的数据（数学、代码、合成推理和智能体数据）。对最终能力影响很大。', at: 'data#mixture' },
  'synthetic-data': { t: '合成数据', en: 'synthetic data', d: '由模型生成的训练数据：改写网页、生成教科书和习题、蒸馏推理过程等。2024 年后成为预训练的重要组成部分。', at: 'data#synthetic' },
  rephrasing: { t: '改写', en: 'rephrasing', d: '让模型把已有文本改写成问答、百科、要点等不同形式。不增加新信息，但让知识以多种形式出现，更容易被模型存成可检索的形式。', at: 'data#synthetic' },
  'model-collapse': { t: '模型崩溃', en: 'model collapse', d: '递归地只用前代模型生成的数据训练，分布的长尾逐代消失，最终塌缩成少数模式。保留并累积真实数据可以避免。', at: 'data#synthetic' },
  'data-wall': { t: '数据墙', en: 'data wall', d: '公开的高质量人类文本约 300 万亿 token，按现有趋势将在 2026–2032 年间用完（Epoch AI 估计）。', at: 'data#limits' },
  memorization: { t: '记忆（训练数据）', en: 'memorization', d: '模型逐字背下并能复现部分训练数据。随模型规模、数据重复次数和提示长度增长，去重可显著缓解。', at: 'data#limits' },

  // ---- scaling (scaling.html)
  'power-law': { t: '幂律', en: 'power law', d: String.raw`\(y = Kx^{-\alpha}\)：在双对数坐标里是斜率为 \(-\alpha\) 的直线。\(x\) 增加 10 倍，\(y\) 变为 \(10^{-\alpha}\) 倍。`, at: 'scaling#z-loglog' },
  'scaling-law': { t: '规模定律', en: 'scaling law', d: String.raw`损失随参数量、数据量、算力按幂律下降的经验规律，例如 \(L(N,D) = E + A/N^\alpha + B/D^\beta\)。用于从小规模实验外推大模型的表现。`, at: 'scaling#powerlaw' },
  'irreducible-loss': { t: '不可约损失', en: 'irreducible loss', d: String.raw`规模定律中的常数项 \(E\)：数据本身的熵，无论模型多大、数据多多都消不掉。`, at: 'scaling#z-floor' },
  overtraining: { t: '过度训练', en: 'overtraining', d: '用远超训练算力最优值的数据训练较小的模型（如 Llama 3 8B 用 15T token，约每参数 1900 个）。训练多花算力，换来推理更便宜。', at: 'scaling#infer' },
  emergence: { t: '涌现', en: 'emergent abilities', d: '某些任务的表现在模型达到一定规模后看似突然出现。很大程度上可由不连续的评分方式解释（如精确匹配）。', at: 'scaling#emergence' },
  adam: { t: 'Adam', en: 'Adam optimizer', d: String.raw`维护梯度的滑动平均 \(\mathbf m\) 和梯度平方的滑动平均 \(\mathbf v\)，按 \(\hat{\mathbf m}/\sqrt{\hat{\mathbf v}}\) 更新：动量 + 逐参数自适应步长。每个参数多存两份状态。`, at: 'scaling#optim' },
  adamw: { t: 'AdamW', en: 'AdamW', d: '把权重衰减从梯度中解耦、直接作用于参数的 Adam。2017 年起大模型训练的默认优化器。', at: 'scaling#optim' },
  wsd: { t: 'WSD 调度', en: 'warmup-stable-decay schedule', d: '学习率先预热、再长时间保持恒定、最后 10–20% 快速衰减。可从稳定阶段任意分叉出衰减，便于测规模定律、延长训练和在衰减段换数据。', at: 'scaling#schedule' },
  svd: { t: '奇异值分解', en: 'singular value decomposition (SVD)', d: String.raw`任意矩阵 \(M = U\Sigma V^\top\)：先旋转（\(V^\top\)），再沿各轴按奇异值 \(\sigma_i\ge 0\) 缩放（\(\Sigma\)），再旋转（\(U\)）。最大奇异值即谱范数。`, at: 'scaling#muon' },
  muon: { t: 'Muon', en: 'Muon optimizer', d: String.raw`对隐藏层权重的动量矩阵做正交化后更新：\(W\leftarrow W - \eta\,UV^\top\)，所有奇异方向等幅更新；用牛顿-舒尔茨迭代近似。2025–26 年被 Kimi K2、GLM-4.5、DeepSeek V4 采用。`, at: 'scaling#muon' },
  'loss-spike': { t: '损失尖峰', en: 'loss spike', d: '训练中损失突然暴涨的现象，常与注意力分数或激活值失控有关；严重时需回滚到之前的检查点重来。', at: 'scaling#muon' },

  // ---- sft (sft.html)
  'base-model': { t: '基座模型', en: 'base model', d: '只经过预训练的模型：会续写任何文本，但不会按指令回答。', at: 'sft#base' },
  'post-training': { t: '后训练', en: 'post-training', d: '预训练之后把基座模型变成可用助手的所有步骤：SFT、偏好优化、强化学习、蒸馏等。', at: 'sft#base' },
  sft: { t: '监督微调（SFT）', en: 'supervised fine-tuning', d: '在“指令-回答”对上最小化交叉熵，只对回答部分计算损失，教模型以助手的身份和格式回答。', at: 'sft#z-mask' },
  'superficial-alignment': { t: '浅层对齐假说', en: 'superficial alignment hypothesis', d: '模型的知识和能力几乎全部来自预训练，SFT 只是教它用什么格式和风格说出来（LIMA, 2023）。对弱基座不完全成立。', at: 'sft#what' },
  'reward-model': { t: '奖励模型', en: 'reward model', d: '从“两个回答哪个更好”的比较数据中学出的打分模型，按 Bradley-Terry 模型训练。是人类偏好的不完美代理。', at: 'sft#z-bt' },
  'bradley-terry': { t: 'Bradley-Terry 模型', en: 'Bradley–Terry model', d: String.raw`\(P(y_w\succ y_l) = \sigma(r_w - r_l)\)：比较的胜率只取决于两者的分差。与 Elo 等级分相同。`, at: 'sft#z-bt' },
  dpo: { t: 'DPO', en: 'direct preference optimization', d: String.raw`利用 KL 约束下 RLHF 最优解的闭式形式，直接在偏好对上训练：\(-\log\sigma\big(\beta\log\frac{\pi_\theta(y_w)}{\pi_{\text{ref}}(y_w)} - \beta\log\frac{\pi_\theta(y_l)}{\pi_{\text{ref}}(y_l)}\big)\)。不需要奖励模型和 RL。`, at: 'sft#z-dpo' },
  lora: { t: 'LoRA', en: 'low-rank adaptation', d: String.raw`冻结原权重，只训练低秩增量 \(\Delta W = BA\)（秩 \(r\) 通常 8–64）。可训练参数降到 1% 以下；QLoRA 再把原权重量化到 4 比特。`, at: 'sft#lora' },
  'task-vector': { t: '任务向量', en: 'task vector', d: String.raw`微调后权重减去微调前权重 \(\tau = \theta_{\text{ft}} - \theta_{\text{base}}\)。多个任务向量相加可合并能力，取负可去除行为。`, at: 'sft#merge' },

  // ---- distillation (distillation.html)
  'knowledge-distillation': { t: '知识蒸馏', en: 'knowledge distillation', d: String.raw`用老师模型的输出训练学生模型。经典形式是让学生在温度 \(T\) 下逼近老师的软标签分布（Hinton 等, 2015）。`, at: 'distillation#kd' },
  'offline-distillation': { t: '离线蒸馏', en: 'offline / sequence-level distillation', d: '用老师生成的文本对学生做 SFT。最小化正向 KL；学生只见过老师的前缀，有暴露偏差。', at: 'distillation#kd' },
  opd: { t: '在线策略蒸馏', en: 'on-policy distillation', d: String.raw`学生自己采样回答，老师对每个 token 打分，按 \(A_t = \log\pi_{\text{老师}}(y_t) - \log\pi_\theta(y_t)\) 做策略梯度。最小化反向 KL，信号比 RL 密得多。`, at: 'distillation#onpolicy' },
  seesaw: { t: '跷跷板效应', en: 'seesaw effect', d: '多领域混合后训练时，一个领域变好、另一个变差的相互拉扯（如数学提升而代码下降）。', at: 'distillation#mopd' },
  mopd: { t: '多教师在线蒸馏（MOPD）', en: 'multi-teacher on-policy distillation', d: '先用 RL 训练各领域的专科老师，学生在自己的采样上按题目领域接受对应老师的逐 token 打分，再叠加结果奖励。小米 MiMo-V2-Flash 提出（2026）。', at: 'distillation#mopd' },
  'context-distillation': { t: '上下文蒸馏', en: 'context distillation', d: '以“带着提示或示范的自己”为老师，训练“不带提示的自己”去模仿，把上下文的效果写进权重。SDFT 是它在持续学习上的推广。', at: 'distillation#self' },

  // ---- reasoning (reasoning.html)
  cot: { t: '思维链', en: 'chain of thought (CoT)', d: String.raw`回答前先写出中间推理步骤。写下 \(T\) 个 token，可用的串行计算从 \(L\) 层扩展到约 \(L\times T\) 步，理论上扩展了 Transformer 能计算的函数类。`, at: 'reasoning#why' },
  'self-consistency': { t: '多数投票（自洽性）', en: 'self-consistency', d: '同一问题采样多条推理，取出现最多的答案。正确答案是最常见答案时有效；存在常见的陷阱答案时会稳定地选错。', at: 'reasoning#ttc' },
  overthinking: { t: '过度思考', en: 'overthinking', d: '推理模型在简单问题上写出过长的思考、得到答案后反复验证，浪费算力；有时想得越久越差。', at: 'reasoning#budget' },
  'cot-faithfulness': { t: '思维链忠实性', en: 'CoT faithfulness', d: '思维链是否如实反映了决定答案的因素。实验显示模型受暗示影响时常常不在思维链里承认（约 25–39%）。', at: 'reasoning#faithful' },

  // ---- agents (agents.html)
  'agent-llm': { t: '智能体', en: 'agent', d: '模型 + 一组工具 + 一个循环：模型输出思考和工具调用，外部程序执行并把结果追加回上下文，直到任务完成。', at: 'agents#loop' },
  harness: { t: 'harness', en: 'agent harness', d: '智能体循环之外的程序：执行工具、管理上下文、处理权限与错误、规划与验证。同一模型换 harness，分数可差十几个百分点。', at: 'agents#loop' },
  'tool-calling': { t: '工具调用', en: 'tool / function calling', d: '工具用 JSON Schema 描述；模型按约定格式（常包在特殊 token 里）输出调用，harness 解析并执行，结果回填上下文。', at: 'agents#tools' },
  mcp: { t: 'MCP', en: 'Model Context Protocol', d: '应用与工具服务之间的开放协议（Anthropic, 2024-11），服务器提供 tools、resources、prompts，把 N×M 个集成变成 N+M。2025-12 捐给 Linux 基金会。', at: 'agents#tools' },
  'context-engineering': { t: '上下文工程', en: 'context engineering', d: '在多步任务中决定每一步往有限上下文里放什么：保持前缀稳定、清理旧结果、压缩、按需检索、外部记忆、子智能体。', at: 'agents#context' },
  compaction: { t: '压缩（上下文）', en: 'compaction', d: '上下文快满时让模型把历史写成摘要，用摘要替换原文继续工作。会改动前缀、使缓存失效。', at: 'agents#context' },
  subagent: { t: '子智能体', en: 'subagent', d: '在全新上下文中执行子任务、只把结论交回主智能体的智能体。让主上下文保持干净，代价是额外的调用。', at: 'agents#context' },
  rag: { t: 'RAG', en: 'retrieval-augmented generation', d: '先从资料库检索相关片段放进上下文，再让模型回答：切块、嵌入、召回、重排、生成。', at: 'agents#rag' },
  'hybrid-retrieval': { t: '混合检索', en: 'hybrid retrieval', d: String.raw`同时用向量检索（语义）和关键词检索（BM25，精确匹配），常用倒数排名融合 \(\sum 1/(k + \text{rank})\) 合并结果。`, at: 'agents#rag' },
  'agentic-search': { t: '智能体搜索', en: 'agentic search', d: '由模型自己决定搜什么、读什么、是否换关键词再搜，检索成为循环中的一种动作，而非固定流水线。', at: 'agents#rag' },
  'prompt-injection': { t: '提示注入', en: 'prompt injection', d: '工具返回的不可信内容（网页、邮件等）中夹带指令，诱使模型执行。根源是模型无法从结构上区分指令和数据。', at: 'agents#security' },

  // ---- coding (coding.html)
  fim: { t: '中间填空（FIM）', en: 'fill-in-the-middle', d: '训练时把文档重排为“前缀、后缀、中间”并用特殊 token 标记，模型从左到右预测中间段时已看过前后文。编辑器补全依赖它。', at: 'coding#train' },
  'swe-bench': { t: 'SWE-bench', en: 'SWE-bench', d: '用真实 GitHub 仓库的 issue 出题：给出 issue 和修复前的仓库，以 PR 中的测试（FAIL_TO_PASS 与 PASS_TO_PASS）判分。Verified 为人工筛选的 500 题，Pro 更难、更难污染。', at: 'coding#rl-env' },
  'vibe-coding': { t: 'vibe coding', en: 'vibe coding', d: '用自然语言描述需求、接受 AI 的全部修改而不读代码的编程方式（Karpathy, 2025-02）。适合原型，不适合需长期维护的软件。', at: 'coding#forms' },

  // ---- moe (moe.html)
  moe: { t: '混合专家（MoE）', en: 'mixture of experts', d: String.raw`把 MLP 换成 \(E\) 个专家加一个路由器，每个 token 只送给得分最高的 \(k\) 个专家。参数量约为 \(E\) 个专家，计算量约为 \(k\) 个。`, at: 'moe#idea' },
  expert: { t: '专家', en: 'expert', d: 'MoE 层中的一个小 MLP。细粒度 MoE 有几百个专家，外加所有 token 都经过的共享专家。', at: 'moe#idea' },
  router: { t: '路由器', en: 'router / gate', d: String.raw`一个 \(d\times E\) 的线性层，给每个专家打分，选出 top-k 并给出门控权重。与模型一起训练。`, at: 'moe#idea' },
  'routing-collapse': { t: '路由坍缩', en: 'routing collapse', d: '路由器把大部分 token 送给少数专家，其余专家得不到训练。需要辅助损失或无辅助损失的偏置调节来均衡负载。', at: 'moe#balance' },

  // ---- long-context (long-context.html)
  'kv-cache': { t: 'KV 缓存', en: 'KV cache', d: String.raw`生成时缓存历史 token 的 K、V，避免重算。每 token 大小 \(2\times L\times h_{kv}\times d_h\times\) 字节数；长上下文推理时常是显存的主要占用。`, at: 'long-context#kv' },
  gqa: { t: 'GQA', en: 'grouped-query attention', d: '把 Q 头分组，每组共享一组 K/V 头（如 64 个 Q 头配 8 个 KV 头），KV 缓存按比例缩小。2023 年后的默认设计。', at: 'attention#zero-big' },
  mla: { t: 'MLA', en: 'multi-head latent attention', d: '把每个 token 的 K、V 联合压缩为一个低维潜向量（如 512 维）加一个 64 维的 RoPE 向量来缓存，计算时把上投影吸收进 Q 和输出投影。DeepSeek-V2 提出。', at: 'long-context#kv' },
  'flash-attention': { t: 'FlashAttention', en: 'FlashAttention', d: String.raw`把注意力分块在片上 SRAM 中算完、不写出 \(n\times n\) 矩阵的精确实现，借助在线 softmax。显存从 \(O(n^2)\) 降到 \(O(n)\)，速度提升 2–4 倍。`, at: 'long-context#flash' },
  'online-softmax': { t: '在线 softmax', en: 'online softmax', d: String.raw`分块扫描时维护当前最大值 \(m\) 与归一化因子 \(\ell\)，遇到更大值时把已累积的结果乘 \(e^{m - m_{\text{新}}}\) 修正，最终结果与一次性计算完全一致。`, at: 'long-context#flash' },
  'linear-attention': { t: '线性注意力', en: 'linear attention', d: String.raw`去掉 softmax，用结合律把历史压成固定大小的状态 \(S_t = S_{t-1} + \mathbf v_t\mathbf k_t^\top\)，读取 \(\mathbf o_t = S_t\mathbf q_t\)。代价线性、显存常数，但精确回忆能力有限；DeltaNet、KDA 加入误差修正与遗忘门。`, at: 'long-context#linear' },
  ssm: { t: '状态空间模型', en: 'state space model (SSM)', d: '以固定大小的状态做递推、状态更新由输入选择性控制的序列模型，代表是 Mamba。Mamba-2 证明它与一类线性注意力等价。', at: 'long-context#linear' },

  // ---- hardware (hardware.html)
  'tensor-core': { t: '张量核心', en: 'tensor core', d: 'GPU 中专门做小矩阵乘加的电路，一个周期完成上千次乘加；大模型的算力几乎全部来自它。精度越低，吞吐越高。', at: 'hardware#gpu' },
  sram: { t: '片上 SRAM', en: 'on-chip SRAM', d: '紧挨计算单元的高速小容量存储（每个 SM 几百 KB）。高性能内核的关键是让数据在这里被反复使用。', at: 'hardware#gpu' },
  hbm: { t: 'HBM', en: 'high-bandwidth memory', d: '与芯片封装在一起的堆叠显存，容量几十到几百 GB、带宽每秒数 TB。大模型推理常受它的带宽限制。', at: 'hardware#gpu' },
  'arithmetic-intensity': { t: '算术强度', en: 'arithmetic intensity', d: '每从显存读写一个字节所做的运算次数（FLOPs/字节）。低于芯片的“峰值算力 ÷ 带宽”时访存受限，高于时计算受限。', at: 'hardware#roofline' },
  roofline: { t: 'Roofline 模型', en: 'roofline model', d: String.raw`可达性能 \(=\min(P_{\text{峰值}},\ I\times\text{BW})\)：判断一段计算受限于算力还是带宽。单用户解码的强度约为 1，远低于拐点。`, at: 'hardware#roofline' },
  'systolic-array': { t: '脉动阵列', en: 'systolic array', d: '乘加单元组成的网格，权重驻留在单元中，输入数据逐拍流过、部分和沿另一方向累加。TPU 的矩阵单元采用这种结构，能效高但不够灵活。', at: 'hardware#arch' },

  // ---- quantization (quantization.html)
  quantization: { t: '量化', en: 'quantization', d: String.raw`用更少的位数表示权重、激活或 KV 缓存：\(\hat w = s\cdot\operatorname{round}(w/s)\)。省显存、省带宽、能用低精度算力，代价是误差。`, at: 'quantization#why' },
  bpw: { t: '每权重位数（bpw）', en: 'bits per weight', d: '包括缩放因子等开销在内的平均位数：位宽 + 缩放位数 ÷ 组大小。例如 Q4_0 为 4.5、MXFP4 为 4.25。', at: 'quantization#basics' },
  microscaling: { t: '微缩放格式', en: 'microscaling (MX / NVFP4)', d: '每 16 或 32 个低位数共享一个缩放因子的硬件格式：MXFP4 用 E8M0 缩放、组大小 32；NVFP4 用 FP8 缩放、组大小 16，外加张量级缩放。', at: 'quantization#basics' },
  'outlier-features': { t: '离群特征', en: 'outlier features', d: '激活中少数幅度大几十倍的固定通道（约 6.7B 参数以上出现），会撑大缩放因子、毁掉其余数值的精度。', at: 'quantization#outliers' },
  ptq: { t: '训练后量化（PTQ）', en: 'post-training quantization', d: '模型训练完后直接量化，最多用少量校准数据（GPTQ、AWQ、imatrix）。4 位以上通常够用。', at: 'quantization#qat' },
  qat: { t: '量化感知训练（QAT）', en: 'quantization-aware training', d: '训练时前向使用量化后的权重、反向用直通估计器更新高精度潜权重，让模型适应量化网格。低于 4 位基本必需。', at: 'quantization#qat' },
  ste: { t: '直通估计器（STE）', en: 'straight-through estimator', d: '反向传播时把取整当作恒等函数，梯度原样传给潜权重（超出可表示范围时置零），使不可导的量化可以被训练。', at: 'quantization#qat' },

  // ---- serving (serving.html)
  prefill: { t: '预填充', en: 'prefill', d: '一次性处理整个提示、算出全部 KV 缓存和第一个 token 的阶段。大矩阵乘法，计算受限，决定首 token 延迟（TTFT）。', at: 'serving#phases' },
  decode: { t: '解码（阶段）', en: 'decode', d: '之后每步生成一个 token 的阶段。矩阵乘向量，访存受限，决定每 token 间隔（TPOT）；靠批处理提高吞吐。', at: 'serving#phases' },
  goodput: { t: '有效吞吐', en: 'goodput', d: '满足延迟要求（如首 token 与每 token 延迟上限）的那部分吞吐，比单纯的吞吐更能反映服务质量。', at: 'serving#queue' },
  'continuous-batching': { t: '连续批处理', en: 'continuous batching', d: '每个解码步都把已结束的请求换成队列中的新请求，而不是等一整批都结束（Orca, 2022）。', at: 'serving#batching' },
  'paged-attention': { t: 'PagedAttention', en: 'PagedAttention', d: 'KV 缓存按固定大小的块按需分配、用块表映射，借鉴操作系统分页；显存浪费从 60–80% 降到 4% 以下（vLLM, 2023）。', at: 'serving#batching' },
  'prefix-cache': { t: '前缀缓存', en: 'prefix caching', d: '多个请求共享的前缀（系统提示、对话历史、工具说明）只计算一次 KV，之后直接复用。API 对缓存命中的输入大幅降价。', at: 'serving#batching' },
  'spec-decoding': { t: '投机解码', en: 'speculative decoding', d: String.raw`草稿先猜 \(\gamma\) 个 token，大模型一次前向并行验证，按 \(\min(1, p/q)\) 接受、拒绝时从残差分布重抽；输出分布与大模型完全相同，速度提升 2–3 倍。`, at: 'serving#spec' },
  'pd-disagg': { t: '预填充与解码分离', en: 'prefill/decode disaggregation', d: '把预填充和解码放在不同的 GPU 池，KV 缓存经高速网络传输，两类负载互不干扰、分别扩容。', at: 'serving#disagg' },

  // ---- training-systems (training-systems.html)
  recompute: { t: '激活重算', en: 'activation recomputation', d: '前向时只保存少数层的输入，反向时重新计算中间激活，用约 33% 的额外计算换数倍的显存；选择性重算只重算便宜而占显存的部分。', at: 'training-systems#memory' },
  'data-parallel': { t: '数据并行', en: 'data parallelism', d: '每张卡一份完整模型、处理不同数据，每步对梯度做全规约求平均。最简单，但每卡要装下整个模型与优化器状态。', at: 'training-systems#ts0-8' },
  'zero-fsdp': { t: 'ZeRO / FSDP', en: 'ZeRO / fully sharded data parallel', d: '在数据并行的卡之间依次切分优化器状态、梯度、参数（ZeRO-1/2/3），用到时再收集。状态显存约降为 1/n，通信增加。', at: 'training-systems#ts0-8' },
  'tensor-parallel': { t: '张量并行', en: 'tensor parallelism', d: '把每个矩阵乘法按行或列切到多张卡上，每层两次全规约；通信频繁，通常限于一个 NVLink 域内。', at: 'training-systems#parallel' },
  'pipeline-parallel': { t: '流水线并行', en: 'pipeline parallelism', d: String.raw`按层切成 \(p\) 段放在不同机器上，数据切成 \(m\) 个微批次流过；空闲“气泡”比例约 \((p-1)/(m+p-1)\)。`, at: 'training-systems#parallel' },
  mfu: { t: 'MFU', en: 'model FLOPs utilization', d: String.raw`模型理论计算量（每 token \(6N\)）占硬件峰值算力的比例。大规模训练做到 40–50% 就算很好。`, at: 'training-systems#mfu' },

  // ---- on-device (on-device.html)
  'unified-memory': { t: '统一内存', en: 'unified memory', d: 'CPU 与 GPU 共享同一块内存（Apple 芯片、DGX Spark 等）。容量大，能放下大模型；带宽与算力通常低于同价位的独立显卡。', at: 'on-device#mac' },
  npu: { t: 'NPU', en: 'neural processing unit', d: '专为神经网络推理设计的加速器（手机、嵌入式芯片中常见）。算子集合封闭、需专用工具链；擅长计算受限的预填充，解码仍受内存带宽限制。', at: 'on-device#phone' },

  // ---- vlm (vlm.html)
  vit: { t: 'ViT', en: 'Vision Transformer', d: '把图像切成固定大小的 patch，每块投影成一个向量，加位置编码后用 Transformer 编码器处理。几乎所有多模态模型的视觉编码器都是 ViT。', at: 'vlm#vit' },
  patch: { t: 'patch（图像块）', en: 'patch', d: String.raw`图像被切成的 \(P\times P\) 像素小方块（如 14 或 16 像素），相当于图像的“token”。数量与图像面积成正比。`, at: 'vlm#vit' },
  clip: { t: 'CLIP', en: 'Contrastive Language–Image Pre-training', d: '用 4 亿网络图文对，以对比学习同时训练图像编码器和文本编码器，使配对的图文向量相近。支持零样本分类，是多模态模型视觉编码器的起点。', at: 'vlm#clip' },
  contrastive: { t: '对比学习', en: 'contrastive learning', d: String.raw`让配对样本相似、不配对样本不相似的训练方式。CLIP 的损失是 \(N\times N\) 相似度矩阵上按行、按列的交叉熵（InfoNCE），等价于抬高互信息的下界。`, at: 'vlm#clip' },
  llava: { t: 'LLaVA', en: 'Large Language and Vision Assistant', d: '视觉编码器 + 投影层 + 语言模型的多模态范式（2023）：先训投影层对齐，再做视觉指令微调。', at: 'vlm#llava' },
  projector: { t: '投影层', en: 'projector', d: '把视觉编码器输出的向量映射到语言模型嵌入维度的小网络（线性层或两层 MLP），通常配合 2×2 patch 合并。', at: 'vlm#llava' },
  'native-multimodal': { t: '原生多模态', en: 'native multimodal', d: '从预训练阶段就混合图文（及音视频）数据训练的模型，而不是先训好语言模型再“装上眼睛”。', at: 'vlm#llava' },

  // ---- diffusion (diffusion.html)
  'diffusion-model': { t: '扩散模型', en: 'diffusion model', d: String.raw`前向把数据逐步混入高斯噪声 \(\mathbf x_t = a_t\mathbf x_0 + b_t\boldsymbol\varepsilon\)，训练网络去噪；生成时从纯噪声出发反复去噪。图像与视频生成的主流方法。`, at: 'diffusion#forward' },
  'flow-matching': { t: '流匹配', en: 'flow matching / rectified flow', d: String.raw`用直线插值 \(\mathbf x_t = (1-t)\mathbf x_0 + t\boldsymbol\varepsilon\) 定义路径，回归速度 \(\boldsymbol\varepsilon - \mathbf x_0\)，生成时解 ODE。路径更直、少步误差更小；SD3、FLUX 起的标准。`, at: 'diffusion#forward' },
  score: { t: '分数', en: 'score', d: String.raw`对数概率密度的梯度 \(\nabla_{\mathbf x}\log p_t(\mathbf x)\)，指向密度上升最快的方向。由 Tweedie 公式，它等于 \(-\mathbb E[\boldsymbol\varepsilon\mid\mathbf x_t]/b_t\)，即去噪器隐含的信息。`, at: 'diffusion#reverse' },
  cfg: { t: '无分类器引导（CFG）', en: 'classifier-free guidance', d: String.raw`\(\hat\varepsilon = \hat\varepsilon(\varnothing) + w(\hat\varepsilon(c) - \hat\varepsilon(\varnothing))\)：放大条件带来的改变，相当于从 \(p(\mathbf x)p(c\mid\mathbf x)^w\) 采样。更贴题、多样性下降。`, at: 'diffusion#cfg' },

  // ---- image (image.html)
  vae: { t: 'VAE', en: 'variational autoencoder', d: '把图像压缩成小得多的潜表示（每边压缩约 8 倍）并能解码回来的网络。潜空间扩散在它的潜空间里去噪。', at: 'image#latent' },
  'latent-diffusion': { t: '潜空间扩散', en: 'latent diffusion', d: '先用 VAE 把图像压缩成潜图，在潜图上做扩散，最后解码成像素（Stable Diffusion, 2022）。计算量减少数十倍。', at: 'image#latent' },
  dit: { t: 'DiT', en: 'Diffusion Transformer', d: '用 Transformer 处理潜图 patch 的去噪网络，时间步和条件经 adaLN 注入。扩展性好，是 Sora 之后大型图像与视频模型的基础。', at: 'image#backbone' },
  mmdit: { t: 'MMDiT', en: 'multimodal DiT', d: '文本 token 与图像 token 拼成一条序列做联合注意力、两种模态各有权重的 DiT（SD3, 2024）。FLUX、Qwen-Image 沿用。', at: 'image#backbone' },
  sdedit: { t: 'SDEdit（图生图）', en: 'SDEdit', d: '把输入图加噪到中间时刻 s，再从那里去噪。强度 s 越大，保留原图越少、越自由。', at: 'image#strength' },
  controlnet: { t: 'ControlNet', en: 'ControlNet', d: '复制去噪网络的编码器接收边缘、深度、姿态等控制信号，经零初始化的卷积注入冻结的主网络，训练初期不破坏原能力。', at: 'image#control' },
  'unified-model': { t: '理解与生成统一模型', en: 'unified understanding & generation', d: '同一个模型既能看图也能画图，多数在语言模型内部直接做扩散（Transfusion、BAGEL、HunyuanImage 3.0），也有全部用离散图像 token 的（Chameleon、Janus）。', at: 'image#unified' },

  // ---- video (video.html)
  'spacetime-patch': { t: '时空 patch', en: 'spacetime patch', d: '把潜视频沿时间和空间切成的小块（常为 1×2×2），每块一个 token；任意时长、分辨率的视频都变成一串 token（Sora, 2024）。', at: 'video#zero-patch' },
  'diffusion-forcing': { t: 'Diffusion Forcing', en: 'Diffusion Forcing', d: '训练时给每一帧独立的噪声水平，使模型能以“不完美的前帧”为条件逐帧生成，缓解自回归视频的误差累积（2024）。', at: 'video#consistency' },

  // ---- audio (audio.html)
  mel: { t: '梅尔频谱', en: 'mel spectrogram', d: String.raw`每隔约 10 毫秒做一次短时傅里叶变换，把频率按梅尔刻度 \(m = 2595\log_{10}(1 + f/700)\) 分成几十个频带并取对数能量。声音的“图像”表示。`, at: 'audio#zero-mel' },
  asr: { t: '语音识别（ASR）', en: 'automatic speech recognition', d: '把语音转写成文字。Whisper 用编码器读梅尔频谱、解码器像语言模型一样生成文字，68 万小时弱监督数据带来鲁棒性。', at: 'audio#features' },
  'neural-codec': { t: '神经音频编解码器', en: 'neural audio codec', d: '把波形压成每秒几十帧、每帧几个码本编号的网络（SoundStream、EnCodec、Mimi），并能解码还原。让语言模型可以“预测声音 token”。', at: 'audio#codec' },
  rvq: { t: '残差向量量化（RVQ）', en: 'residual vector quantization', d: '第 1 级码本量化原始向量，第 k 级量化前 k−1 级留下的残差；码率 = 帧率 × 级数 × log₂(码本大小)。', at: 'audio#codec' },
  'full-duplex': { t: '全双工对话', en: 'full-duplex dialogue', d: '同时听和说、可随时被打断或插话的语音对话模型（Moshi、GPT-Live）。', at: 'audio#duplex' },

  // ---- spatial (spatial.html)
  nerf: { t: '神经辐射场（NeRF）', en: 'neural radiance field', d: '用一个 MLP 表示场景：输入坐标与视角，输出密度和颜色；沿光线做可微体渲染，从多张照片优化得到。', at: 'spatial#nerf' },
  'volume-rendering': { t: '体渲染', en: 'volume rendering', d: String.raw`沿光线累加 \(C = \sum_i T_i\alpha_i\mathbf c_i\)，\(\alpha_i = 1 - e^{-\sigma_i\delta_i}\)，\(T_i = \prod_{j<i}(1-\alpha_j)\)。来自比尔-朗伯定律，NeRF 与高斯泼溅共用。`, at: 'spatial#nerf' },
  'gaussian-splatting': { t: '3D 高斯泼溅', en: '3D Gaussian splatting', d: '用几百万个带位置、协方差、颜色、不透明度的三维高斯椭球表示场景，投影到屏幕后按深度排序混合，可实时渲染（2023）。', at: 'spatial#gs' },
  sds: { t: '分数蒸馏采样（SDS）', en: 'score distillation sampling', d: '从随机视角渲染三维表示、加噪后让二维扩散模型预测噪声，用预测与真实噪声之差更新三维参数，借二维模型生成三维（DreamFusion, 2022）。', at: 'spatial#gen' },

  // ---- world-models (world-models.html)
  'world-model': { t: '世界模型', en: 'world model', d: String.raw`学习环境动态 \(p(\mathbf s_{t+1}\mid\mathbf s_{\le t}, \mathbf a_t)\) 的模型：给定观测与动作预测下一刻。用于在想象中训练智能体、可交互的视频世界、驾驶与机器人仿真。`, at: 'world-models#what' },
  jepa: { t: 'JEPA', en: 'joint-embedding predictive architecture', d: '只在抽象表示空间里预测未来、不重建像素的自监督架构（LeCun）；用停止梯度与慢速更新的目标编码器防止表示塌缩。V-JEPA 2 用它做机器人规划。', at: 'world-models#debate' },

  // ---- embodied (embodied.html)
  vla: { t: 'VLA', en: 'vision-language-action model', d: '以视觉语言模型为骨干、直接输出机器人动作的模型：动作可离散成 token（RT-2），或由流匹配动作专家生成连续的动作块（π0）。', at: 'embodied#vla' },
  'behavior-cloning': { t: '行为克隆', en: 'behavior cloning', d: String.raw`用监督学习模仿专家在各状态下的动作。偏离示范后的状态没见过，误差累积，代价上界随步数平方增长（\(T^2\varepsilon\)）；DAgger 降为线性。`, at: 'embodied#bc' },
  wam: { t: '世界动作模型', en: 'world action model', d: '以大规模预训练的视频世界模型为骨干，在预测未来画面的同时解码出动作的机器人策略（2026 年兴起，如 NVIDIA DreamZero）。', at: 'embodied#wam' },

  // ---- interpretability (interpretability.html)
  probe: { t: '线性探针', en: 'linear probe', d: String.raw`在冻结模型的某层激活上训练一个逻辑回归 \(\sigma(\mathbf w\cdot\mathbf h + b)\) 预测某个概念。能读出说明信息存在，不说明模型使用了它。`, at: 'interpretability#tools' },
  'logit-lens': { t: 'logit lens', en: 'logit lens', d: '把中间层的残差流直接乘以输出矩阵解码，看模型此刻“最想说”哪个词，观察预测逐层形成的过程。', at: 'interpretability#tools' },
  superposition: { t: '叠加', en: 'superposition', d: '模型用远少于概念数的维度表示概念：稀疏的特征以近似正交的方向共享同一空间，导致神经元多义。', at: 'interpretability#superposition' },
  sae: { t: '稀疏自编码器（SAE）', en: 'sparse autoencoder', d: String.raw`把激活展开成大量稀疏特征 \(\mathbf f = \operatorname{ReLU}(W_e\mathbf h + \mathbf b)\) 并还原，用 L1 惩罚使特征稀疏、单义。用于拆解叠加。`, at: 'interpretability#superposition' },
  circuit: { t: '电路（可解释性）', en: 'circuit', d: '若干特征或注意力头相互作用、共同完成某个计算的子网络，如归纳头、多跳推理路径。归因图用来追踪它们。', at: 'interpretability#circuits' },

  // ---- evaluation (evaluation.html)
  contamination: { t: '数据污染', en: 'data contamination', d: '测试题（或其答案）进入了模型的训练数据，使分数反映的是“见过”而非“会做”。2026 年行业默认公开基准已被污染。', at: 'evaluation#static' },
  'time-horizon': { t: '时间跨度（METR）', en: 'time horizon', d: '人类专家需要多长时间的任务，模型有 50%（或 80%）的把握完成。2019–2025 年约每 7 个月翻倍，2024 年后约每 4 个月。', at: 'evaluation#horizon' },

  // ---- alignment (alignment.html)
  alignment: { t: '对齐', en: 'alignment', d: '让模型的行为符合我们真正的意图，而不只是符合给它的代理目标（奖励、标注、分数）。分为外部对齐（目标写对了没有）与内部对齐（模型学到的是不是这个目标）。', at: 'alignment#what' },
  'emergent-misalignment': { t: '涌现不对齐', en: 'emergent misalignment', d: '在一个狭窄的坏行为（如写有漏洞的代码、钻奖励空子）上训练，模型却在无关场景中表现出广泛的恶意。似乎由一个低维的“坏人设”方向承载。', at: 'alignment#hacking' },
  monitorability: { t: '可监控性', en: 'CoT monitorability', d: '思维链能否如实反映模型的打算、从而被用来发现不当行为。训练时惩罚思维链里的“坏想法”会破坏它：模型学会不写出来。', at: 'alignment#monitor' },
  'alignment-faking': { t: '对齐伪装', en: 'alignment faking', d: '模型在认为自己会被训练时假装顺从，以避免价值观被修改；在认为不会被训练时表现不同（Greenblatt 等, 2024）。', at: 'alignment#scheming' },

  // ---- jailbreak (jailbreak.html)
  jailbreak: { t: '越狱', en: 'jailbreak', d: '用户有意绕过模型的安全限制，让它输出本应拒绝的内容。攻击者是用户自己，区别于第三方发起的提示注入。', at: 'jailbreak#what' },
  'attack-success-rate': { t: '攻击成功率', en: 'attack success rate (ASR)', d: '一组有害请求中被成功突破的比例。依赖评审模型判断“是否真的有害”，不同论文的数字常不可直接比较。', at: 'jailbreak#what' },
  'universal-jailbreak': { t: '通用越狱', en: 'universal jailbreak', d: '同一个方法能突破几乎所有请求的越狱。一旦公开任何人都能复制，是防御方最关注的目标。', at: 'jailbreak#what' },
  'shallow-alignment': { t: '浅层对齐', en: 'shallow safety alignment', d: '对齐模型与基座模型的差异集中在回答的前几个 token（“抱歉，我不能……”）；开头一旦被换掉，后续生成接近基座模型（Qi 等, ICLR 2025）。', at: 'jailbreak#why' },
  abliteration: { t: '消融去拒绝', en: 'abliteration', d: '把拒绝方向从模型权重中投影掉，使模型几乎不再拒绝。无需训练，有权重就能做。', at: 'jailbreak#why' },

  // ---- science (science.html)
  msa: { t: '多序列比对', en: 'multiple sequence alignment (MSA)', d: '把同一个蛋白在许多物种中的序列逐位置对齐：每行一个物种，每列一个位置。AlphaFold 从中读取共进化信号。', at: 'science#protein' },
  coevolution: { t: '共进化', en: 'coevolution', d: '结构上相互接触的两个位置，一个突变后常需另一个补偿突变，于是在比对中“一起变”。由此可推断哪些位置相邻。', at: 'science#protein' },
  'formal-proof': { t: '形式化证明', en: 'formal proof (Lean)', d: '用 Lean 等证明助手把推理写成程序，由一个小内核机械检查；通过即不可能出错（除非命题本身写错）。为数学 RL 提供零噪声奖励。', at: 'science#math' },

  // ---- industry (industry.html)
  capex: { t: '资本开支', en: 'capital expenditure (capex)', d: '购买芯片、建设机房等长期资产的支出。四大云厂商 2026 年的指引合计超过 7000 亿美元。', at: 'industry#money' },
  depreciation: { t: '折旧', en: 'depreciation', d: '把一次性的设备投入按使用年限平摊为每年的成本。年限越长，当期利润越好看，现金流不变。', at: 'industry#bubble' },
  'fair-use': { t: '合理使用', en: 'fair use', d: '美国版权法的抗辩：综合考虑使用目的（是否转化性）、作品性质、使用量和对原作市场的影响，判断未经许可的使用是否合法。', at: 'industry#copyright' },
  'ai-act': { t: 'AI 法案（欧盟）', en: 'EU AI Act', d: '按风险分级的统一立法。2024 年生效，通用模型义务 2025-08 开始，高风险条款经 2026 年修订推迟到 2027–2028 年。', at: 'industry#regulation' },

  // ---- appendix (nn-basics.html)
  'matrix-rank': { t: '秩', en: 'matrix rank', d: '矩阵真正用到的独立方向个数。低秩矩阵可写成两个瘦矩阵之积，LoRA 即基于此。', at: 'nn-basics#vectors' },
  'orthogonal-matrix': { t: '正交矩阵', en: 'orthogonal matrix', d: String.raw`满足 \(Q^\top Q = I\) 的矩阵（旋转或镜像），不改变长度与夹角，逆就是转置。`, at: 'nn-basics#vectors' },
  eigenvalue: { t: '特征值', en: 'eigenvalue', d: String.raw`若 \(A\mathbf v = \lambda\mathbf v\)，矩阵对方向 \(\mathbf v\) 只拉伸 \(\lambda\) 倍。反复相乘时该方向按 \(\lambda^k\) 增长或衰减。`, at: 'nn-basics#vectors' },
  'conditional-prob': { t: '条件概率', en: 'conditional probability', d: String.raw`\(P(A\mid B) = P(A,B)/P(B)\)：已知 B 时 A 的概率。语言模型把序列概率拆成逐个条件概率之积。`, at: 'nn-basics#prob' },
  expectation: { t: '期望', en: 'expectation', d: String.raw`按概率加权的平均值。\(n\) 个独立样本平均值的方差是单个的 \(1/n\)。`, at: 'nn-basics#prob' },
  covariance: { t: '协方差矩阵', en: 'covariance matrix', d: '对角线是各变量的方差，非对角线衡量两两是否一起变化。特征向量是高斯等高线椭圆的轴。', at: 'nn-basics#gauss' },
  activation: { t: '激活函数', en: 'activation function', d: '每层线性变换后逐元素施加的非线性函数（ReLU、GELU、SiLU）。没有它，多层网络等价于一层。', at: 'nn-basics#nn' },
  gradient: { t: '梯度', en: 'gradient', d: '损失对每个参数的偏导数组成的向量，指向损失增长最快的方向；梯度下降沿其反方向更新参数。', at: 'nn-basics#gd' },
  'learning-rate': { t: '学习率', en: 'learning rate', d: String.raw`梯度下降每步走多远。二次损失下必须小于 \(2/\lambda_{\max}\)，否则发散。`, at: 'nn-basics#gd' },
  'chain-rule': { t: '链式法则', en: 'chain rule', d: String.raw`\(\partial L/\partial x = (\partial L/\partial y)(\partial y/\partial x)\)。反向传播从损失出发逐层套用它。`, at: 'nn-basics#backprop' },
  jacobian: { t: '雅可比矩阵', en: 'Jacobian', d: String.raw`向量函数的导数矩阵，第 \(i\) 行第 \(j\) 列是 \(\partial y_i/\partial x_j\)。梯度反传就是连乘各层的雅可比矩阵。`, at: 'nn-basics#backprop' },
  overfitting: { t: '过拟合', en: 'overfitting', d: '训练集上越来越好、没见过的数据上变差：背下了细节与噪声而非规律。', at: 'nn-basics#fit' },
  'floating-point': { t: '浮点数', en: 'floating point', d: '符号 + 指数 + 尾数。指数位决定范围，尾数位决定精度（相对间隔 2 的负尾数位数次方）。BF16 = 8 位指数 + 7 位尾数。', at: 'nn-basics#float' },

  // ---- prologue (prologue.html)
  pretraining: { t: '预训练', en: 'pretraining', d: '先在海量无标注文本上学“预测下一个（或被遮住的）词”，得到通用的基座模型，再用少量数据适配具体任务。2018 年由 GPT 与 BERT 确立。', at: 'prologue#arc' },
  'bitter-lesson': { t: '苦涩的教训', en: 'the bitter lesson', d: 'Sutton（2019）：能随算力扩展的通用方法（搜索与学习），最终总会胜过融入人类知识的专门方法。', at: 'prologue#lessons' },

  // ---- video (upgrade 2026-10-20)
  'temporal-redundancy': { t: "时间冗余", en: "temporal redundancy", d: "相邻帧之间大部分像素几乎不变，下一帧大多可以从上一帧猜出来。传统视频编码靠它压缩两三百倍；视频 VAE 因此能在时间上压 4 倍而丢失很少。", at: "video#zero-redundancy" },
  'latent-frame': { t: "潜帧", en: "latent frame", d: "视频 VAE 压缩后时间方向上的一“帧”。因果 VAE 下 \\(N_t = 1 + (T-1)/f_t\\)：第一帧单独一个，之后每 \\(f_t\\)（常为 4）帧一个。", at: "video#zero-vae" },
  'causal-vae': { t: "3D 因果 VAE", en: "causal 3D VAE", d: "时间方向只用因果卷积的视频 VAE：编码第 t 帧只看它和之前的帧。第一帧单独编码，所以一张图就是 1 帧的视频；还能分块编码任意长度（MAGVIT-v2 起，CogVideoX、HunyuanVideo、Wan 沿用）。", at: "video#zero-vae" },
  'joint-image-video': { t: "图像视频联合训练", en: "joint image-video training", d: "把图片当作只有 1 帧的视频，与视频混在一起训练同一个模型：从图片学外观与概念，从视频学运动。因果 VAE 让两者的潜变量同分布。", at: "video#zero-vae" },
  nfe: { t: "函数评估次数（NFE）", en: "number of function evaluations", d: "一次生成里去噪网络被调用的总次数，衡量采样成本。50 步加 CFG 是 100 次；少步蒸馏后常为 1–8 次。", at: "video#zero-gen" },
  'full-3d-attention': { t: "全 3D 注意力", en: "full 3D attention", d: "视频的每个 token 直接看所有潜帧的所有位置，代价 \\((N_tN_s)^2\\)。能直接关联运动物体在不同帧里的位置，CogVideoX 之后的大模型多采用。", at: "video#arch" },
  'factorized-attention': { t: "时空分解注意力", en: "factorized space-time attention", d: "先在每个潜帧内部做空间注意力，再在每个空间位置上沿时间做注意力，代价 \\(N_tN_s^2 + N_sN_t^2\\)，约为全 3D 的 \\(1/N_t\\)；代价是运动物体的跨帧关联要两跳。", at: "video#arch" },
  'noise-augmentation': { t: "上下文加噪", en: "context noise augmentation", d: "训练自回归模型时给上下文帧加噪（并告诉模型噪声水平），让它习惯不完美的上下文。真实与生成上下文的 KL 按 \\(a^2/b^2\\) 缩小，代价是上下文信息变少（GameNGen、Diffusion Forcing）。", at: "video#ar-noise" },
  'self-forcing': { t: "Self Forcing", en: "Self Forcing", d: "训练时就按推理方式自回归滚动生成（KV 缓存），以自己生成的帧为上下文，对整段视频用分布匹配等损失训练；训练与推理的上下文分布一致。4 步去噪，单张 H100 每秒 17 帧（2025-06）。", at: "video#ar-self" },
  'noise-stage-moe': { t: "按噪声分工的 MoE", en: "noise-stage mixture of experts", d: "把去噪过程按噪声水平切段，各段用不同的专家网络，每步只激活一个；没有路由器，由去噪进度决定。Wan 2.2：高噪声专家管构图与运动、低噪声专家管细节，总 27B、每步 14B（2025-07）。", at: "video#frontier-moe" },
  snr: { t: "信噪比（SNR）", en: "signal-to-noise ratio", d: "扩散里 \\(\\mathrm{SNR}(t) = a_t^2/b_t^2\\)，流匹配下为 \\(((1-t)/t)^2\\)。分量 \\(k\\) 的 \\(a_t^2\\lambda_k/b_t^2 = 1\\) 时它“确定了一半”，分界频率随 \\(\\sqrt{\\mathrm{SNR}}\\) 由低向高移动。", at: "video#frontier-moe" },
  'av-joint': { t: "音视频联合生成", en: "joint audio-video generation", d: "在同一个去噪过程里同时生成视频和音频（对白、音效、音乐），常用视频塔 + 音频塔逐层交叉注意力、共享时间坐标对齐。Veo 3（2025-05）首先商用。", at: "video#frontier-audio" },
  'multi-shot': { t: "多镜头生成", en: "multi-shot generation", d: "一次生成包含多个镜头与镜头切换的视频，并让角色、风格跨镜头保持一致；常在位置编码中加入镜头信息（Seedance 1.0, 2025）。", at: "video#frontier-shots" },
  'chain-of-frames': { t: "帧链", en: "chain-of-frames", d: "把视觉任务表述成“画面接下来怎样变化”，让视频模型逐帧演化出答案（走迷宫、分割、补全），类比语言模型的思维链（Wiedemer 等, 2025）。", at: "video#physics" },
  'cascade-diffusion': { t: "级联扩散", en: "cascaded diffusion", d: "先用基础模型生成低分辨率、低帧率的样本，再用多个超分模型逐级提高分辨率与帧率。Imagen Video 用 7 个模型从 16×40×24、3 fps 放大到 128×1280×768、24 fps（2022）。", at: "video#history" },

  // ---- evaluation (upgrade 2026-10-20)
  benchmark: { t: "基准", en: "benchmark", d: "一组固定的题目、标准答案和判分规则。它是从“这一类题”的总体里抽出的一份样本，分数是对真实能力的有噪声的估计。", at: "evaluation#ev0-toy" },
  'standard-error': { t: "标准误", en: "standard error (SE)", d: "估计量（如准确率）在“换一份题再考一次”时的标准差。准确率的标准误是 \\(\\sqrt{p(1-p)/n}\\)，题目翻 4 倍才减半。", at: "evaluation#ev0-se" },
  'confidence-interval': { t: "置信区间", en: "confidence interval", d: "\\(\\hat p \\pm 1.96\\,\\mathrm{SE}\\)：反复抽题、每次都这样算一个区间，95% 的区间会盖住真实值。区间包含 0 的差距，统计上不能断言存在。", at: "evaluation#ev0-ci" },
  'paired-test': { t: "配对比较", en: "paired comparison", d: "两个模型在同一组题上比较时，逐题求差再估计差的均值。两者一起涨落的部分（协方差）被扣掉，方差通常小一半左右。", at: "evaluation#ev0-paired" },
  'stat-power': { t: "统计功效", en: "statistical power", d: "真实差距存在时，一次评测能得出“显著”结论的概率。80% 功效需要约 \\(2.8^2\\sigma_d^2/\\delta^2\\) 道题，差距减半，题目要翻 4 倍。", at: "evaluation#ev0-paired" },
  'clustered-se': { t: "聚类标准误", en: "clustered standard error", d: "题目成组出现（同一篇文章、同一个仓库）时按组计算的标准误。组内相关 \\(\\rho\\)、每组 \\(m\\) 题时，方差放大 \\(1+(m-1)\\rho\\) 倍。", at: "evaluation#ev0-cluster" },
  bootstrap: { t: "自助法", en: "bootstrap", d: "从已有数据里有放回地重抽同样多的样本、重算统计量，重复上千次，用结果的散布当误差棒。不需要推公式，任何统计量都能用。", at: "evaluation#ev0-cluster" },
  saturation: { t: "饱和（基准）", en: "benchmark saturation", d: "前沿模型的分数挤到天花板附近，模型之间的差距小于统计误差和标注错误，基准不再能区分模型。", at: "evaluation#static" },
  'pass-hat-k': { t: "pass^k", en: "pass^k", d: "同一任务独立做 \\(k\\) 次、全部成功的概率，衡量可靠性；单题为 \\(p^k\\)。与“至少一次成功”的 pass@k 相对，随 \\(k\\) 增大而下降。", at: "evaluation#passk" },
  elo: { t: "Elo 等级分", en: "Elo rating", d: "每赛一场按“实际结果 − 预期胜率”调整分数：\\(R \\leftarrow R + K(S - E)\\)。它是 Bradley-Terry 似然上步长固定的随机梯度，结果依赖对局顺序。", at: "evaluation#arena" },
  'style-control': { t: "风格控制", en: "style control", d: "在 Bradley-Terry 回归里加入回答长度、标题、列表、加粗等风格变量，把“风格带来的胜率”从模型分数里分离出去（LMArena, 2024-08）。", at: "evaluation#arena" },
  'llm-judge': { t: "LLM 评委", en: "LLM-as-a-judge", d: "用强模型代替人给回答打分或做两两比较。便宜，但偏爱特定位置、更长的回答和与自己风格相近的回答。", at: "evaluation#arena" },
  irt: { t: "项目反应理论（IRT）", en: "item response theory", d: "心理测量学的模型：做对的概率 \\(\\sigma(a_j(\\theta_i - b_j))\\) 只取决于能力 \\(\\theta\\) 与难度 \\(b\\) 之差。Elo 和 METR 时间跨度都是它的特例。", at: "evaluation#horizon" },
  'construct-validity': { t: "构念效度", en: "construct validity", d: "一个测量是否真的测到了它声称要测的能力（“推理”“安全”“编程”），而不是题目格式、应试技巧或别的相关因素。", at: "evaluation#generations" },
  'eval-awareness': { t: "评估意识", en: "evaluation awareness", d: "模型识别出自己正在被测试，并可能因此改变行为。说出口的只是下限；它让评测结果与真实部署中的行为可能不一致。", at: "evaluation#validity" },

  // ---- serving (upgrade 2026-10-20)
  ttft: { t: "首 token 延迟", en: "time to first token (TTFT)", d: "从请求到达到第一个输出 token 返回的时间，等于排队 + 预填充 + 网络。长提示、高负载时主要被预填充和排队拉长。", at: "serving#life-prefill" },
  tpot: { t: "每 token 间隔", en: "time per output token (TPOT)", d: "第一个 token 之后平均每生成一个 token 的时间 \\((T_{\\text{结束}} - T_{\\text{首}})/(n_{\\text{输出}} - 1)\\)，即用户看到的“打字速度”。由解码一步的时长决定，批越大、上下文越长越慢。", at: "serving#life-decode" },
  slo: { t: "服务等级目标", en: "service level objective (SLO)", d: "服务方给延迟定的目标，例如“90% 的请求首 token ≤ 2 秒、每 token ≤ 50 毫秒”。有效吞吐只计算达标的请求。", at: 'serving#queue' },
  'littles-law': { t: "利特尔定律", en: "Little's law", d: "稳定系统里的平均请求数 = 到达率 × 平均停留时间，\\(\\bar N = \\lambda\\bar T\\)，与到达和服务时间的分布无关（Little, 1961）。", at: "serving#queue" },
  'load-factor': { t: "负载率", en: "utilization / load factor", d: "到达率与最大服务率之比 \\(\\rho = \\lambda/\\mu\\)。M/M/1 队列的平均停留时间是 \\(S/(1-\\rho)\\)，\\(\\rho\\) 接近 1 时发散，所以服务必须留余量。", at: "serving#queue" },
  'kv-fragmentation': { t: "显存碎片", en: "KV-cache fragmentation", d: "预留了却没存 token 的 KV 显存：按最大长度预留造成的内部碎片，以及大小不一的空洞放不下新请求的外部碎片。分页把它压到每个请求最多半块。", at: "serving#batching" },
  'chunked-prefill': { t: "分块预填充", en: "chunked prefill", d: "把长提示切成几百到几千 token 的块，与正在解码的请求拼进同一步，用解码留下的空闲算力完成预填充，避免长提示让所有人卡顿（Sarathi-Serve, 2024）。", at: "serving#disagg" },
  'kv-aware-routing': { t: "KV 感知路由", en: "KV-aware routing", d: "多台机器部署同一模型时，把请求发给已经缓存了它前缀 KV 的那台，以提高前缀缓存命中率（NVIDIA Dynamo、llm-d）。", at: "serving#prefix" },
  'wide-ep': { t: "宽专家并行", en: "wide expert parallelism", d: "大型 MoE 解码时把专家分散到几十到上百张卡（如 DeepSeek 2025-03 的线上解码：18 个节点、144 路；V3 报告里的最小部署单元是 40 节点 320 卡），注意力部分用数据并行，token 经全对全通信送到专家所在的卡。", at: "serving#scale" },

  // ---- hardware (upgrade 2026-10-20)
  sm: { t: "流式多处理器（SM）", en: "streaming multiprocessor", d: "GPU 的基本计算单元。H100 有 132 个，每个含 4 个张量核心、256 KB 寄存器和最多 228 KB 共享内存，可同时驻留 2048 个线程。", at: "hardware#hw0-why" },
  warp: { t: "线程束", en: "warp", d: "32 个线程组成的调度单位，同一时刻执行同一条指令、处理不同数据（SIMT）。一个线程束等数据时，SM 立刻切换到另一个，以此藏住访存延迟。", at: "hardware#hw0-why" },
  'gpu-kernel': { t: "内核（GPU）", en: "GPU kernel", d: "在 GPU 上运行的一个函数，由许多线程块组成的网格执行，每个线程块分到一个 SM 上。一次矩阵乘法通常就是一个内核；性能主要取决于它怎样安排数据。", at: "hardware#hw0-why" },
  'wave-quant': { t: "波次量化", en: "wave quantization", d: "输出块数不是 SM 数的整数倍时，最后一“波”只有部分 SM 有活干造成的浪费。H100 上 2048 块要 16 波，损失 3%；小矩阵可损失一半。", at: "hardware#hw0-walk" },
  tma: { t: "TMA（张量内存加速器）", en: "Tensor Memory Accelerator", d: "H100 起的硬件拷贝单元：一个线程发一条指令，就能在显存与共享内存之间异步搬运一整块多维张量，其余线程不必参与。", at: "hardware#hw0-walk" },
  'compute-bound': { t: "计算受限", en: "compute-bound", d: "耗时由“运算数 ÷ 峰值算力”决定的情形：算术强度高于拐点，例如预填充时的大矩阵乘法。", at: "hardware#hw0-bound" },
  'memory-bound': { t: "访存受限", en: "memory-bound", d: "耗时由“读写字节数 ÷ 显存带宽”决定的情形：算术强度低于拐点，例如单用户解码、逐元素操作。此时加算力无用，减少字节数（量化、融合、拼批）才有用。", at: "hardware#hw0-bound" },
  'ridge-point': { t: "拐点", en: "ridge point", d: "Roofline 上访存受限与计算受限的分界 \\(I^\\ast = P/\\text{BW}\\)，是硬件参数。H100 的 BF16 约 295 FLOPs/字节；细长矩阵乘法要一次处理约 \\(Pb/(2\\,\\text{BW})\\) 个 token 才能越过它。", at: "hardware#roofline" },
  'memory-wall': { t: "内存墙", en: "memory wall", d: "芯片算力增长远快于显存带宽和互连带宽（二十年约 6 万倍对 100 倍），越来越多的计算受限于搬数据而不是算数据。", at: "hardware#roofline" },
  tiling: { t: "分块", en: "tiling", d: "把输出切成 \\(T\\times T\\) 的块在片上累加，使每个读入的数被用 \\(T\\) 次，访存降到 \\(1/T\\)。块大小受片上容量限制，强度只随容量的平方根增长。", at: "hardware#tiling" },
  'kernel-fusion': { t: "算子融合", en: "kernel fusion", d: "把多个操作合并到一个内核里，中间结果留在片上、不写回显存。逐元素操作的耗时几乎全是读写，融合后可降到零；FlashAttention 是其极致。", at: "hardware#tiling" },
  'scale-up': { t: "扩展域", en: "scale-up domain", d: "用 NVLink、TPU ICI 等专用链路连成的一组加速器，可直接读写彼此显存，每卡带宽为网卡的十倍左右。H100 时代 8 卡，GB200 NVL72 为 72 卡；张量并行和专家并行要放在域内。", at: "hardware#interconnect" },
  'scale-out': { t: "横向扩展网络", en: "scale-out network", d: "扩展域之间的 InfiniBand / 以太网（RDMA）网络，每卡约 50–100 GB/s，适合通信少的数据并行和流水线并行。", at: "hardware#interconnect" },
  nvlink: { t: "NVLink", en: "NVLink", d: "NVIDIA 的 GPU 间专用高速链路，配合 NVLink 交换机组成扩展域。每卡双向带宽：H100 900 GB/s，B200 1.8 TB/s，Rubin 3.6 TB/s。", at: "hardware#interconnect" },
  tf32: { t: "TF32", en: "TensorFloat-32", d: "A100 引入的张量核心格式：8 位指数（与 FP32 同范围）、10 位尾数。FP32 代码不改即可使用张量核心，算力为普通 FP32 的约 8 倍。", at: "hardware#generations" },
  'sparse-24': { t: "2:4 结构化稀疏", en: "2:4 structured sparsity", d: "每 4 个权重中恰好 2 个为零时，张量核心跳过零、算力账面翻倍（A100 起支持）。在大语言模型上很少使用；规格表上的“稀疏”数字是稠密的两倍。", at: "hardware#generations" },
  'transformer-engine': { t: "Transformer Engine", en: "Transformer Engine", d: "H100 起的 FP8 训练与推理方案：按每个张量最近若干步的最大绝对值选缩放因子（延迟缩放）；哪些层用 FP8 由框架决定。", at: "hardware#generations" },
  'tile-programming': { t: "分块级编程", en: "tile-based programming", d: "写“一个线程块对几个小块做什么”，线程映射、共享内存和流水线交给编译器。代表是 Triton（2021），以及 ThunderKittens、TileLang、CUDA Tile 等。", at: "hardware#software" },
  'dl-compiler': { t: "深度学习编译器", en: "deep learning compiler", d: "拿到整个计算图，做算子融合和内存规划，再为目标硬件生成代码，如 XLA（JAX / TPU）、TorchInductor（torch.compile，GPU 上生成 Triton 内核）。", at: "hardware#software" },
  afd: { t: '注意力与 FFN 分离（AFD）', en: 'attention–FFN disaggregation', d: '推理时把注意力层（每个用户私有的 KV，吃显存容量和带宽）与 FFN / 专家层（共享权重）放到不同的卡或芯片上；在 GPU 集群里 FFN 一侧通常受算力限制，在小批、低延迟的部署里受读权重的带宽限制。', at: 'serving#scale' },

  // ---- image (upgrade 2026-10-20)
  'text-encoder': { t: "文本编码器", en: "text encoder", d: "把提示词变成一串向量（每个 token 一个）的预训练语言网络，通常冻结、每张图只跑一次。从 CLIP（77 个 token）到 T5，再到 2025 年后的多模态大模型，决定了模型能听懂多复杂的提示。", at: "image#img0-text" },
  'timestep-shift': { t: "时间步偏移（分辨率相关）", en: "resolution-dependent timestep shift", d: "图越大，同一噪声水平破坏的信息越少，所以把时间步往噪声一侧挪：\\(t_m = \\alpha t_n/(1 + (\\alpha-1)t_n)\\)，\\(\\alpha = \\sqrt{P_m/P_n}\\)（\\(P_m, P_n\\) 为两种分辨率的像素数）。SD3 在 1024² 上取 \\(\\alpha = 3\\)。", at: "image#img0-shift" },
  'joint-attention': { t: "联合注意力", en: "joint attention", d: "把文本 token 与图像 token 拼成一条序列做一次自注意力，两种模态各用一套投影权重（MMDiT）。对图像 token 相当于自注意力与交叉注意力的自适应混合；文本表示也随画面逐层更新。", at: "image#backbone" },
  inpainting: { t: "局部重绘", en: "inpainting", d: "只重新生成掩码内的区域：每一步把掩码外换回原图加噪到当前水平的版本 \\(\\mathbf m\\odot\\mathbf x_t + (1-\\mathbf m)\\odot(a_t\\mathbf x_{\\text{原图}} + b_t\\boldsymbol\\varepsilon)\\)，或训练以掩码和原图为额外输入的专门模型。", at: "image#control" },
  'in-context-editing': { t: "上下文内编辑", en: "in-context image editing", d: "把参考图编码成 token，与目标图 token 拼进同一条序列，靠联合注意力直接参照参考图生成或修改，不需要额外的控制网络（FLUX.1 Kontext、Qwen-Image-Edit, 2025）。", at: "image#control" },
  dreambooth: { t: "DreamBooth", en: "DreamBooth", d: "用 3–5 张照片和带稀有标识符的提示词（“a [V] dog”）微调整个去噪网络，让模型学会一个具体的人物或物体（2022）。容易语言漂移和背图，需配合先验保持损失。", at: "image#personal" },
  'prior-preservation': { t: "先验保持损失", en: "class-specific prior preservation loss", d: "个性化微调时，额外用原模型自己生成的类别图片（“a dog”）做去噪训练，让一般类别的输出保持不变，防止整个类别被带偏（语言漂移）。", at: "image#personal" },
  'guidance-distillation': { t: "引导蒸馏", en: "guidance distillation", d: "训练学生网络以引导强度 w 为输入、一遍前向就复现 CFG（有条件与无条件两遍外推）的结果，把每步的计算减半（FLUX.1 [dev]）。", at: "image#fast" },
  'adversarial-distillation': { t: "对抗蒸馏", en: "adversarial diffusion distillation", d: "学生用一到几步生成，由判别器判断像不像真图、像 GAN 一样训练，常配合老师的蒸馏信号。ADD（SDXL Turbo）的判别器用 DINOv2 特征；LADD（SD3 Turbo、FLUX.1 [schnell]）改用老师自己的潜空间特征。", at: "image#fast" },
  dmd: { t: "分布匹配蒸馏（DMD）", en: "distribution matching distillation", d: "让一步生成器的输出分布匹配老师：反向 KL 的梯度是 \\(\\mathbb E[(\\mathbf s_{\\text{假}} - \\mathbf s_{\\text{真}})^\\top\\partial\\mathbf x/\\partial\\theta]\\)，真分数来自老师，假分数由另一个在生成器输出上训练的扩散模型给出（2023；DMD2, 2024）。", at: "image#fast" },
  fid: { t: "FID", en: "Fréchet Inception Distance", d: "把真实图与生成图的 Inception-v3 特征各拟合成高斯，算两者的 Fréchet（Wasserstein-2）距离 \\(\\|\\boldsymbol\\mu_r-\\boldsymbol\\mu_g\\|^2 + \\operatorname{Tr}(\\Sigma_r+\\Sigma_g-2(\\Sigma_r^{1/2}\\Sigma_g\\Sigma_r^{1/2})^{1/2})\\)。只看前两阶矩，依赖样本数（有偏）和特征网络。", at: "image#eval" },

  // ---- training-systems (upgrade 2026-10-20)
  'global-batch': { t: "全局批", en: "global batch", d: "一个训练步用到的全部数据，例如 Llama 2 每步约 400 万 token（1024 条 × 4096）。超过“临界批大小”后，加大全局批不再能成比例地减少步数。", at: "training-systems#ts0-step" },
  'saved-activations': { t: "激活值（训练时保存的）", en: "saved activations", d: "前向时每层留给反向用的中间结果。一层约 \\(nBd\\,(34 + 5an/d)\\) 字节，与 token 数成正比、与参数量无关；用 FlashAttention 或重算可以大幅减少。", at: "training-systems#ts0-step" },
  'micro-batch': { t: "微批次", en: "micro-batch", d: "把全局批切成的小份，一次只做一个微批次的前向和反向。梯度累积与流水线并行都以它为单位。", at: "training-systems#ts0-step" },
  'grad-accum': { t: "梯度累积", en: "gradient accumulation", d: "依次算若干个微批次的梯度并相加，最后只更新一次参数。与一次算完整批在数学上等价，用来在显存有限时使用大批量。", at: "training-systems#ts0-step" },
  'mixed-precision': { t: "混合精度训练", en: "mixed-precision training", d: "前向和反向用 16 位（BF16/FP16）计算，另存一份 FP32 主权重累积更新（2017）。加上 Adam 的两个 FP32 状态，每参数约 16 字节。", at: "training-systems#ts0-mem" },
  'master-weights': { t: "主权重", en: "master weights", d: "优化器保存并更新的 FP32 权重副本。BF16 在 0.02 附近的间隔约 1.2×10⁻⁴，小于半个间隔的更新会被舍掉；FP32 副本保证它们被累积下来。", at: "training-systems#ts0-mem" },
  'all-reduce': { t: "全规约", en: "all-reduce", d: "每张卡都得到所有卡数据之和（或平均）的集合通信，数据并行用它同步梯度。等于一次规约散发加一次全收集。", at: "training-systems#ts0-8" },
  'reduce-scatter': { t: "规约散发", en: "reduce-scatter", d: "对所有卡的数据求和，结果切成 \\(k\\) 份，每张卡只拿到其中一份。ZeRO 用它把梯度总和分给各自负责的卡。", at: "training-systems#ts0-8" },
  'all-gather': { t: "全收集", en: "all-gather", d: "每张卡把自己的那 \\(1/k\\) 发给其它所有卡，大家拼回完整的一份。ZeRO-3 用它在用到时临时收集一层的完整权重。", at: "training-systems#ts0-8" },
  straggler: { t: "掉队者", en: "straggler", d: "还在工作、但明显变慢的卡或机器。同步训练每一步都要等最慢的那张卡，一个掉队者能拖慢上千张卡。", at: "training-systems#ts0-1000" },
  'context-parallel': { t: "上下文并行", en: "context parallelism", d: "把一条长序列切成几段分给几张卡；注意力所需的 K、V 通过环形传递（环形注意力）或全收集获得。用于训练 128K 以上的上下文。", at: "training-systems#parallel" },
  'expert-parallel': { t: "专家并行", en: "expert parallelism", d: "MoE 的专家分布在不同卡上，每层用两次全对全通信把 token 送到专家所在的卡、再取回。", at: "moe#parallel" },
  'sequence-parallel': { t: "序列并行", en: "sequence parallelism", d: "在张量并行之上，把 LayerNorm、dropout 等逐 token 的区域沿序列切成 \\(t\\) 份；全规约拆成全收集与规约散发，通信量不变，这部分激活降到 \\(1/t\\)（2022）。", at: "training-systems#tp" },
  'pipeline-bubble': { t: "流水线气泡", en: "pipeline bubble", d: "流水线灌满和排空时部分段空等的时间，占比 \\((p-1)/(m+p-1)\\)。交错调度降到约 \\(1/v\\)，零气泡调度把权重梯度的计算挪进空闲里。", at: "training-systems#pipeline" },
  'ring-allreduce': { t: "环形全规约", en: "ring all-reduce", d: "\\(k\\) 张卡排成环，先 \\(k-1\\) 步规约散发、再 \\(k-1\\) 步全收集，每卡收发 \\(2(k-1)S/k\\)，几乎与卡数无关，已达带宽下界；延迟随 \\(k\\) 线性增长。", at: "training-systems#comm" },
  hfu: { t: "HFU", en: "hardware FLOPs utilization", d: "把激活重算等额外计算也算进去的硬件算力利用率，总是不低于 MFU。PaLM 540B：MFU 46.2%，HFU 57.8%。", at: 'training-systems#mfu' },
  'loss-scaling': { t: "损失缩放", en: "loss scaling", d: "把损失乘一个大数，让梯度落进 FP16 的可表示范围，更新前再除回去；溢出时把倍数减半并跳过这一步。BF16 范围与 FP32 相同，不再需要它。", at: "training-systems#precision" },
  'fine-grained-scaling': { t: "细粒度缩放", en: "fine-grained (tile/block-wise) scaling", d: "每一小块数据（如激活每 1×128、权重每 128×128）各用一个缩放因子再转成 FP8，块内动态范围小，不易下溢。DeepSeek-V3 靠它让所有张量都用 E4M3。", at: "training-systems#precision" },
  mtbf: { t: "平均故障间隔", en: "mean time between failures (MTBF)", d: "两次故障之间的平均时间 \\(M\\)。同步训练的故障率按卡数相加，\\(M\\) 与卡数成反比：Llama 3 在 1.6 万卡上约 3 小时。", at: "training-systems#faults" },
  checkpoint: { t: "检查点", en: "checkpoint", d: "训练状态（权重、优化器状态、数据位置、随机数状态）的完整快照，故障后从这里重来。最优保存间隔约 \\(\\sqrt{2CM}\\)（Young, 1974）。", at: "training-systems#faults" },
  sdc: { t: "静默数据错误", en: "silent data corruption (SDC)", d: "芯片算错了却不报错，只表现为损失曲线异常。Gemini 的规模上每一两周就会影响一次训练，要靠确定性重放和主动扫描找出坏机器。", at: "training-systems#faults" },
  'colocated-rl': { t: "训练与推理共置", en: "colocated RL", d: "同一批卡轮流运行推理引擎（采样）和训练引擎（更新），每步切换并同步权重。省卡、简单，但要等一批里最长的回答写完。", at: "training-systems#rl-infra" },
  'async-rl': { t: "异步 RL", en: "asynchronous RL", d: "采样和训练放在两组卡上同时运行，训练使用几步之前的策略生成的数据；吞吐更高，但要用重要性采样修正、限制样本陈旧度。", at: "training-systems#rl-infra" },

  // ---- moe (upgrade 2026-10-20)
  'token-choice': { t: "top-k 路由（token 选专家）", en: "top-k routing / token choice", d: "每个 token 按路由分数挑出最高的 k 个专家，再把这几个的概率重新归一化成门控权重。与“专家挑 token”的 expert choice 相对。", at: "moe#toy-gate" },
  'capacity-factor': { t: "容量因子", en: "capacity factor", d: "每个专家每批最多处理的分配数是平均负载 \\(kT/E\\) 的几倍：\\(C = \\lfloor c\\,kT/E\\rfloor\\)。训练常用 1.0–1.25，超出容量的分配被丢弃。", at: "moe#toy-cap" },
  'token-dropping': { t: "丢 token", en: "token dropping", d: "专家超出容量时，多出来的分配不经过该专家，只靠残差连接把输入传下去。即使路由完全均匀，随机波动也会造成约 0.4/√λ 的丢弃（容量因子为 1 时）。", at: "moe#toy-cap" },
  'active-params': { t: "激活参数", en: "activated parameters", d: "每个 token 实际参与计算的参数量，决定每 token 的计算量（前向约 2 倍）；总参数决定显存。DeepSeek-V3 总参数 671B、激活 37B。", at: "moe#toy-params" },
  'aux-loss': { t: "负载均衡辅助损失", en: "auxiliary load-balancing loss", d: "\\(\\alpha E\\sum_i f_iP_i\\)：\\(f_i\\) 是实际分给专家 \\(i\\) 的比例（不可导），\\(P_i\\) 是平均路由概率（可导）。均匀时取最小值（\\(f\\approx P\\) 时） \\(\\alpha\\)；系数太大会扭曲路由。", at: "moe#balance" },
  'aux-free-balance': { t: "无辅助损失均衡", en: "auxiliary-loss-free load balancing", d: "给每个专家一个偏置 \\(b_i\\)，只在选 top-k 时加到分数上，不进门控权重和梯度；每步按负载调整：超载减、空闲加。相当于给专家定“价格”（DeepSeek-V3）。", at: "moe#auxfree" },
  'router-z-loss': { t: "路由 z-loss", en: "router z-loss", d: "\\(\\frac{c_z}{T}\\sum_t(\\log\\sum_j e^{z_{t,j}})^2\\)：惩罚路由 logit 的整体大小，消除 softmax 的平移自由度，避免低精度下的舍入误差放大（ST-MoE, 2022）。", at: "moe#stability" },
  'fine-grained-experts': { t: "细粒度专家", en: "fine-grained experts", d: "把每个专家切成几份更小的专家，专家数和每个 token 选的个数同比例增加；总参数和计算量不变，组合数暴增（DeepSeekMoE, 2024）。", at: "moe#fine" },
  'shared-expert': { t: "共享专家", en: "shared expert", d: "所有 token 都经过、不参与路由的专家，负责通用知识，让路由专家更专注。DeepSeek-V3 每层 1 个，Kimi K3 每层 2 个；Qwen3 的 MoE 不用。", at: "moe#fine" },
  'expert-granularity': { t: "粒度（专家粒度）", en: "expert granularity", d: "\\(G = d_{\\text{ff}}/d_{\\text{expert}}\\)：标准 MLP 中间维度与单个专家中间维度之比。激活参数不变时，\\(G\\) 越大专家越小、每 token 选得越多（Krajewski 等, 2024）。", at: "moe#laws" },
  'efficiency-leverage': { t: "效率杠杆", en: "efficiency leverage (EL)", d: "稠密模型达到同样效果所需的算力除以 MoE 所需的算力。主要由激活比例和训练总算力决定（蚂蚁 Ling 团队, 2025）。", at: "moe#laws" },
  'all-to-all': { t: "全对全通信", en: "all-to-all", d: "每张卡都向每张卡发送各不相同的数据。MoE 每层两次：分发（dispatch）与收回（combine），每 token 约 k·d·(发+收字节数)。", at: "moe#parallel" },
  'conditional-memory': { t: "条件记忆", en: "conditional memory", d: "按前面几个 token 直接查一张巨大的 n-gram 嵌入表、再与隐藏状态融合；与 MoE 的“条件计算”并列的另一种稀疏（DeepSeek Engram, 2026）。", at: "moe#memory" },
  upcycling: { t: "升级改造", en: "sparse upcycling", d: "把训练好的稠密模型的 MLP 复制成多个专家作为初始值，再加路由器继续训练，复用已花的预训练算力（Komatsuzaki 等, 2022）。", at: "moe#history" },

  // ---- agents (upgrade 2026-10-20)
  react: { t: "ReAct", en: "ReAct (reasoning + acting)", d: "2022 年提出的智能体写法：在提示中让模型交替写“思考—行动—观察”，行动是调用外部 API，观察是返回结果。今天的智能体循环仍是这个结构。", at: "agents#loop" },
  observation: { t: "观察", en: "observation", d: "工具执行后写回上下文的结果（命令输出、文件内容、网页、报错信息）。下一次调用时模型读到它，再决定下一步。", at: "agents#a0-exec" },
  'parallel-tool-calls': { t: "并行工具调用", en: "parallel tool calls", d: "模型在一次输出里同时发出几个互不依赖的调用，harness 并行执行、一起写回，省掉几轮模型调用和等待。", at: "agents#a0-count" },
  'agentic-rl': { t: "智能体强化学习", en: "agentic RL", d: "在真实或模拟的工具环境（终端、浏览器、代码仓库）里采样多轮“思考—调用—观察”轨迹，按任务结果更新模型。2025 年后模型会用工具、能坚持长任务主要靠它。", at: "agents#a0-map" },
  'computer-use': { t: "计算机使用", en: "computer use", d: "把整台电脑当作工具：观察是屏幕截图，动作是点击坐标、输入文字、按快捷键。能操作任何给人用的软件，代价是慢、贵、容易点错。Anthropic 2024-10 推出。", at: "agents#tools" },
  'external-memory': { t: "外部记忆", en: "external memory", d: "把计划、待办、进展笔记写进文件等上下文之外的存储，需要时再读回。长度不受窗口限制，也不会在压缩中丢失。", at: "agents#context" },
  'context-reset': { t: "上下文重置", en: "context reset", d: "不在原地压缩，而是让智能体把进展和下一步写成交接文件，再开一个全新的上下文从文件读起。用于跨多个会话的长任务。", at: "agents#context" },
  'dense-retrieval': { t: "稠密检索", en: "dense retrieval", d: "查询和文档各自编码成一个稠密向量，用点积 \\(\\mathbf e_q\\cdot\\mathbf e_d\\) 打分；文档向量离线算好，查询时做近似最近邻搜索。擅长同义改写，不擅长精确匹配。", at: "agents#rag" },
  'cross-encoder': { t: "交叉编码器", en: "cross-encoder", d: "把查询和文档拼在一起送进同一个模型直接打分，比分开编码更准，但每一对都要算一次，所以只用来给召回的少量候选重排。", at: "agents#rag" },
  'recall-at-k': { t: "召回率@k", en: "recall@k", d: "在一组测试查询上，正确的文档块出现在前 k 个检索结果里的比例。只衡量“找没找到”，不管排第几。", at: "agents#rag" },
  'deep-research': { t: "深度研究", en: "deep research", d: "自己决定搜什么、读哪些页面、何时换关键词，连续搜索几十上百次再写成带引用报告的智能体；2025 年起多用端到端 RL 训练。", at: "agents#rag" },
  'agent-half-life': { t: "半衰期（智能体）", en: "half-life of agent success", d: "每步致命错误率为 \\(\\lambda\\) 时，成功率随步数指数衰减，降到 50% 需要 \\(\\ln 2/\\lambda\\approx 0.69/\\lambda\\) 步；80% 把握的长度约为它的三分之一。", at: "agents#long" },
  'orchestrator-worker': { t: "编排者-工作者", en: "orchestrator-worker", d: "最常用的多智能体结构：一个主智能体拆分任务、汇总结果，若干子智能体在各自的干净上下文里并行工作。", at: "agents#multi" },
  'lethal-trifecta': { t: "致命三要素", en: "lethal trifecta", d: "Simon Willison 提出：智能体同时能读私密数据、会接触不可信内容、能向外发送信息时，提示注入就能把私密数据偷出去。去掉任意一项或加人工确认可阻断。", at: "agents#security" },

  // ---- coding (upgrade 2026-10-20)
  issue: { t: "issue（问题报告）", en: "issue", d: "用户或开发者在项目页面上提交的问题报告：bug、需求或疑问。编程智能体和 SWE-bench 都把 issue 当作任务描述。", at: "coding#c0-repo" },
  'unit-test': { t: "单元测试", en: "unit test", d: "一小段自动运行的检查：给函数一个固定输入，断言输出等于期望值，相等为“通过”，否则“失败”并报告哪里不对。", at: "coding#c0-repo" },
  'test-coverage': { t: "测试覆盖", en: "test coverage", d: "测试实际检查到了哪些输入和代码路径。没被覆盖的路径里，bug 可以在“测试全部通过”的情况下一直存在。", at: "coding#c0-repo" },
  'fault-localization': { t: "定位（故障定位）", en: "fault localization", d: "从问题描述找到该改的文件、函数和行。真实仓库里往往是修 bug 最难的一步；智能体靠搜索和按需读取来做，而不是把大量代码塞进上下文。", at: "coding#c0-locate" },
  'repro-test': { t: "复现测试", en: "reproduction test", d: "修 bug 之前先写的、能稳定触发这个 bug 因而当前一定失败的测试。修好后它变为通过，并留下来防止复发；对应 SWE-bench 的 FAIL_TO_PASS 测试。", at: "coding#c0-repro" },
  'code-patch': { t: "补丁（diff）", en: "patch / diff", d: "对代码的一组修改，记录在哪个文件删掉了哪几行、加上了哪几行。编程智能体最终交付的就是一个补丁。", at: "coding#c0-edit" },
  'execution-feedback': { t: "执行反馈", en: "execution feedback", d: "运行代码得到的结果（通过、失败、报错信息）回到模型的上下文，让它据此修改。编程智能体能“改了再跑”的基础，也是代码 RL 奖励的来源。", at: "coding#c0-edit" },
  regression: { t: "回归", en: "regression", d: "一次修改把原来能用的功能弄坏了。防回归的测试对应 SWE-bench 的 PASS_TO_PASS 测试。", at: "coding#c0-edit" },
  'false-pass': { t: "误放率", en: "false-pass rate", d: "一个错误的补丁仍然通过全部测试的概率，记作 \\(\\varphi\\)。它决定了“通过测试”有多可信，也决定了 RL 会不会学会针对测试取巧。", at: "coding#c0-why" },
  verifier: { t: "验证器", en: "verifier", d: "能自动判断一个输出对不对的程序：单元测试、编译器、类型检查、证明检查器。测试是不完美的验证器：一般不冤枉正确的补丁，但会放过一部分错误的。", at: "coding#c0-why" },
  'verifier-precision': { t: "精确率（验证器的）", en: "verifier precision", d: "通过验证的输出里真正正确的比例，\\(\\eta = p/\\big(p + (1-p)\\varphi\\big)\\)。它是“改了再跑”和“多采样再筛选”成功率的天花板。", at: "coding#c0-why" },
  'repo-level': { t: "仓库级上下文", en: "repository-level context", d: "把同一仓库的多个文件拼成长序列来训练或推理（DeepSeek-Coder 按依赖关系排序，StarCoder 2 按仓库分组），让模型学会跨文件的引用。", at: "coding#train" },
  'swe-env': { t: "软件工程 RL 环境", en: "software engineering RL environment", d: "一道题 = 装好依赖的容器镜像（修复前的仓库）+ 任务描述 + 判分测试；智能体在其中跑完一条轨迹，测试全部通过得 1 分。来源有人工整理、注入 bug、从提交历史挖掘。", at: "coding#rl-env" },
  'special-casing': { t: "对测试写特例", en: "special-casing", d: "在代码里专门针对测试用例的输入返回期望值（“如果输入正好是这个，就返回那个”），让测试通过而问题并没有修好。钻奖励空子在代码里最常见的形式。", at: "coding#verify" },
  'hidden-tests': { t: "隐藏测试", en: "hidden tests / held-out tests", d: "判分时额外运行、智能体看不到的测试。能压低偷懒补丁的误放率，但挡不住修改测试文件这类“改掉判分者”的做法。", at: "coding#verify" },
  humaneval: { t: "HumanEval", en: "HumanEval", d: "Codex 论文（2021）发布的 164 道手写 Python 函数题，每题平均约 7.7 个单元测试。2024 年已饱和，测试太少也让它的误放率很高。", at: "coding#train" },
  'sample-filter': { t: "采样加筛选", en: "generate-and-filter", d: "对同一任务采样多个候选，只保留通过验证器（如测试）的，再从中挑一个提交。成功率随采样数上升，但上限是验证器的精确率。", at: "coding#select" },
  'background-agent': { t: "后台编程智能体", en: "background coding agent", d: "在云端沙盒里异步运行、不需要人盯着、可连续工作数小时到数周的编程智能体，常多个并行，直接提交 PR。验证器的质量决定它能走多远。", at: "coding#forms" },
  rct: { t: "随机对照试验", en: "randomized controlled trial (RCT)", d: "用随机分配决定谁（或哪个任务）接受处理，再比较结果。随机保证两组在看不见的因素上平均相同，差异才能归因于处理本身。", at: "coding#productivity" },
  amdahl: { t: "阿姆达尔定律", en: "Amdahl's law", d: "只加速一部分工作时，整体加速的上限由没被加速的部分决定：只加速占比 \\(f\\) 的部分，整体最多快 \\(1/(1-f)\\) 倍。", at: "coding#productivity" },
  slopsquatting: { t: "slopsquatting", en: "slopsquatting", d: "攻击者抢先注册模型常“幻觉”出的、并不存在的软件包名，放入恶意代码，等用户照着 AI 的建议安装。", at: "coding#quality" },
  aci: { t: '智能体-计算机接口（ACI）', en: 'agent-computer interface', d: '为模型量身设计的工具与反馈格式（如带行号的文件查看、带语法检查的编辑命令）。SWE-agent（2024）只改接口就把 SWE-bench Lite 从 11.0% 提到 18.0%。', at: 'agents#harness' },

  // ---- audio (upgrade 2026-10-20)
  'sample-rate': { t: "采样率", en: "sample rate", d: "每秒对波形测量多少次（\\(f_s\\)）。能无失真记录的最高频率是 \\(f_s/2\\)（奈奎斯特频率）。识别常用 16 kHz，合成 24 kHz，音乐 44.1/48 kHz。", at: "audio#zero-wave" },
  f0: { t: "基频（F0）", en: "fundamental frequency", d: "周期性声音（如元音）每秒重复的次数，听起来就是音高；男声约 85–155 Hz，女声约 165–255 Hz。波形可拆成基频及其整数倍的谐波。", at: "audio#zero-freq" },
  stft: { t: "短时傅里叶变换（STFT）", en: "short-time Fourier transform", d: "每隔一个步长取一段短窗口做傅里叶变换，按时间排成“时间 × 频率”的频谱图。语音常用 25 毫秒窗、10 毫秒步长，每秒 100 帧。", at: "audio#zero-mel" },
  'tf-resolution': { t: "时间–频率分辨率的取舍", en: "time–frequency resolution trade-off", d: "窗长 \\(T_w\\) 越长，频率分得越细（约 \\(2/T_w\\)），时间分得越粗（约 \\(T_w/2\\)，Hann 窗的有效宽度）；两者的乘积有下限（Gabor 极限）。", at: "audio#zero-mel" },
  vocoder: { t: "声码器", en: "vocoder", d: "从频谱或其它中间表示重建波形的模型。梅尔频谱丢掉了相位，生成语音时必须靠它把相位找回来（WaveNet、HiFi-GAN）。", at: "audio#zero-mel" },
  'speech-ssl': { t: "自监督语音表示", en: "self-supervised speech representation", d: "不用文字标注、只靠“遮住一部分音频再猜”学到的表示（wav2vec 2.0、HuBERT）。学到的特征接近音素，少量标注即可微调出识别器。", at: "audio#features" },
  'semantic-token': { t: "语义 token", en: "semantic token", d: "对语音特征离散化得到的编号，来源有三种：自监督特征聚类、从这类特征蒸馏、用识别模型监督，主要记录“发的是什么音”，几乎不记录说话人。AudioLM、Mimi 的第 1 级码本都属于这一类。", at: "audio#features" },
  'weak-supervision': { t: "弱监督", en: "weak supervision", d: "用大量质量不完美的标注（如网上视频的字幕）代替少量精确标注。Whisper 用 68 万小时这样的数据训练语音识别。", at: "audio#features" },
  vq: { t: "向量量化（VQ）", en: "vector quantization", d: "把连续向量换成码本中离它最近的码字的编号；一个编号占 \\(\\log_2 K\\) 比特。让连续信号变成语言模型能预测的离散 token。", at: "audio#codec" },
  codebook: { t: "码本", en: "codebook", d: "向量量化用的一张向量表，表中每个向量叫码字；编码时取最近码字的编号，解码时查表换回码字。", at: "audio#codec" },
  'acoustic-token': { t: "声学 token", en: "acoustic token", d: "编解码器里补充音色、韵律、录音环境等细节的码本编号（RVQ 的后几级），与只记录内容的语义 token 相对。", at: "audio#codec" },
  'delay-pattern': { t: "延迟模式", en: "delay pattern", d: "多码本 token 的一种排法：第 \\(k\\) 级整体推后 \\(k-1\\) 步，每步并行生成各级。共 \\(T+N_q-1\\) 步（\\(N_q\\) 为码本级数），保留了“同一帧先粗后细”的依赖（MusicGen、Moshi）。", at: "audio#arrange" },
  'depth-transformer': { t: "深度 Transformer", en: "depth transformer (RQ-Transformer)", d: "大模型沿时间每帧走一步给出上下文向量，小模型在帧内逐级生成多个码本编号。精确符合链式法则，大模型步数只有帧数（Moshi；Qwen3-Omni 的 MTP 模块同理）。", at: "audio#arrange" },
  'zero-shot-tts': { t: "零样本语音合成", en: "zero-shot TTS", d: "不为新说话人训练，只用几秒钟的录音作提示，就用这个声音读出任意文字（VALL-E）。也是声音克隆滥用的来源。", at: "audio#tts" },
  'cascade-voice': { t: "级联语音系统（三段式）", en: "cascaded voice pipeline", d: "语音识别 → 语言模型 → 语音合成串起来的语音助手。各段可独立替换，但延迟串行相加，语气等非文字信息会丢失。", at: "audio#latency" },
  'first-packet': { t: "首包延迟", en: "first-packet latency", d: "语音模型从输入结束到第一段可播放音频出来的时间，相当于语音模型的首 token 延迟。Qwen3-Omni 报告的理论值为 234 毫秒。", at: "audio#latency" },
  'semantic-vad': { t: "语义判停", en: "semantic VAD / turn detection", d: "按内容和语调判断用户是否说完，而不只看静音多久。等价于贝叶斯更新 \\(P(\\text{说完}\\mid s) = p_0/(p_0 + (1-p_0)S(s))\\)：先验 \\(p_0\\) 越高，需要等的越短。", at: "audio#latency" },
  'turn-taking': { t: "话轮转换", en: "turn-taking", d: "对话中决定什么时候接过话头。人与人之间的间隔平均约 200 毫秒，靠的是提前预测对方何时说完。", at: "audio#duplex" },
  backchannel: { t: "附和语", en: "backchannel", d: "听话人发出的“嗯”“对”等不打算接过话头的短反馈。全双工模型既要会说，也要能分辨它不是打断。", at: "audio#duplex" },
  'inner-monologue': { t: "内心独白", en: "inner monologue", d: "Moshi 的做法：说话的同时生成与语音时间对齐的文字 token，先“想”出字再生成声音，把文本语言模型的知识带进语音模型。", at: "audio#duplex" },
  rtf: { t: "实时率（RTF）", en: "real-time factor", d: "处理一段声音所需的计算时间除以这段声音的时长。流式模型必须小于 1，否则延迟会随时间累积。", at: "audio#duplex" },
  'thinker-talker': { t: "Thinker–Talker", en: "Thinker–Talker architecture", d: "Qwen-Omni 系列的结构：Thinker（多模态语言模型）负责理解与思考并输出文字，Talker 读取它输出的文字（Qwen2.5-Omni 还读取隐藏状态）流式生成语音编码。", at: "audio#duplex" },

  // ---- world-models (upgrade 2026-10-20)
  'model-based-rl': { t: "基于模型的强化学习", en: "model-based reinforcement learning", d: "先学一个环境模型（世界模型），再用它规划或在想象中训练策略的强化学习；省下真实交互，代价是模型误差会被策略利用。", at: "world-models#what" },
  'model-free-rl': { t: "无模型强化学习", en: "model-free reinforcement learning", d: "不学环境模型、直接从真实交互中学习策略和价值的强化学习。PPO、GRPO 都属于这一类；语言模型的 RL 几乎都是无模型的。", at: "world-models#what" },
  'transition-model': { t: "转移模型", en: "transition model", d: "世界模型的核心部分：在状态 \\(\\mathbf s\\) 做动作 \\(\\mathbf a\\) 后下一个状态的分布 \\(p(\\mathbf s'\\mid\\mathbf s,\\mathbf a)\\)。表格情形可以直接计数估计，一般情形用神经网络近似。", at: "world-models#wm0-predict" },
  'latent-state': { t: "潜状态", en: "latent state", d: "编码器把高维观测（画面）压成的短向量；世界模型在它上面预测下一步，需要时再解码回画面。不同方法对它“必须保留什么”的要求不同。", at: "world-models#wm0-latent" },
  'partial-observability': { t: "部分可观测", en: "partial observability", d: "单个观测不包含全部状态（例如一帧画面看不出速度）。对策是给模型一个汇总历史的记忆，如 RSSM 里的确定性状态 h。", at: "world-models#wm0-latent" },
  mpc: { t: "模型预测控制（MPC）", en: "model predictive control", d: "用模型想象 H 步、选出最好的动作序列，只执行第一步，观察真实结果后重新规划。每步从真实状态出发，模型误差不会一路累积。", at: "world-models#wm0-plan" },
  'planning-horizon': { t: "规划视野", en: "planning / imagination horizon", d: "规划或想象时往前看的步数 H。太短要依赖价值函数补尾巴，太长则模型误差累积；Dreamer 取 15，MuZero 训练时展开 5 步。", at: "world-models#wm0-plan" },
  'model-exploitation': { t: "钻模型的空子", en: "model exploitation", d: "规划器或策略专挑模型错得对自己有利的地方（低估风险、凭空出现的捷径），在模型里分数高、在现实中却差。与“钻奖励空子”同类。", at: "world-models#wm0-error" },
  rssm: { t: "RSSM（循环状态空间模型）", en: "recurrent state-space model", d: "由 PlaNet 提出、Dreamer 沿用的世界模型结构：确定性记忆 h（循环网络）加随机潜变量 z；编码器看画面给出后验，动力学预测器只凭记忆给出先验。", at: "world-models#rssm" },
  elbo: { t: "证据下界（ELBO）", en: "evidence lower bound", d: "用近似后验 \\(q\\) 和 Jensen 不等式得到的对数似然下界：重建项减去 \\(\\mathrm{KL}[q\\|p]\\)。VAE 与 Dreamer 世界模型的训练目标都来自它。", at: "world-models#rssm" },
  'free-bits': { t: "free bits", en: "free bits", d: "KL 低于一个阈值（DreamerV3 取 1 nat）时不再惩罚，避免 KL 项把潜状态里的信息挤掉、导致塌缩。", at: "world-models#rssm" },
  imagination: { t: "想象训练", en: "learning in imagination", d: "从真实状态出发，让策略在世界模型里展开 H 步想象轨迹，用想象出的奖励和价值训练策略，不接触真实环境。Dreamer 的核心。", at: "world-models#rl" },
  'lambda-return': { t: "λ-回报", en: "λ-return", d: "在“一步奖励 + 下一步价值估计”和“更长的实际或想象奖励”之间按 \\(\\lambda\\) 插值的回报目标；\\(\\lambda=0\\) 全信价值网络，\\(\\lambda=1\\) 用完整的 H 步回报。与 GAE 中的 λ 同义。", at: "world-models#rl" },
  mcts: { t: "蒙特卡洛树搜索（MCTS）", en: "Monte Carlo tree search", d: "反复沿“看起来有希望又没探索够”的路径展开搜索树、给新节点估价并回传，最后按根节点各动作的访问次数决定策略。AlphaZero 用真实棋规，MuZero 用学到的模型。", at: "world-models#muzero" },
  'value-equivalence': { t: "价值等价", en: "value equivalence", d: "若用模型做贝尔曼更新得到的结果与真实环境相同，模型就“够用”，不必在每个细节上像真实世界。MuZero 的理论依据（Grimm 等, 2020）。", at: "world-models#muzero" },
  'compounding-error': { t: "误差累积", en: "compounding error", d: "模型的输出又作为下一步的输入，单步误差 \\(\\varepsilon\\) 被放大系数 \\(L\\)（每步对已有误差的放大，受世界本身和模型自身两方面影响）反复放大：\\(H\\) 步后约 \\(\\varepsilon(L^H-1)/(L-1)\\)。想象视野受限、视频漂移的根源。", at: "world-models#drift" },
  'optimizers-curse': { t: "优化者的诅咒", en: "optimizer's curse", d: "在一组有噪声的估计里挑最大的那个，挑出来的估计平均偏高：选中的往往是被高估最多的候选。打分误差越大、候选越多，越严重。", at: "world-models#drift" },
  'inverse-dynamics': { t: "逆动力学模型", en: "inverse dynamics model", d: "给定相邻两帧（或前后状态），推断中间发生了什么动作的模型；与“给状态和动作预测下一帧”的世界模型方向相反。", at: "world-models#latent-action" },
  'latent-action': { t: "潜动作", en: "latent action", d: "从无标注视频中学出的离散“动作码”：逆动力学编码器从小码本里挑一个码，解码器只凭过去和这个码还原下一帧。Genie 用 8 个码；有干扰时码可能记录干扰而非动作。", at: "world-models#latent-action" },
  'retrieval-memory': { t: "检索式记忆", en: "retrieval-based memory", d: "把过去的帧连同相机位置、时间戳存起来，生成新画面时只取回视野重叠最多的几帧放进上下文，让世界模型“记得”离开过的地方。", at: "world-models#memory" },
  'closed-loop-sim': { t: "闭环仿真", en: "closed-loop simulation", d: "被测策略在仿真里行动，仿真按它的动作生成下一刻的传感器数据，策略再做下一个决定；与回放录像的开环测试相对。", at: "world-models#physical" },
  'representation-collapse': { t: "表示塌缩", en: "representation collapse", d: "只要求表示之间可预测时，把所有输入映射成同一个常数是平凡最优解。JEPA 用停止梯度与滑动平均目标、LeJEPA 用分布约束、对比学习用负样本来防止。", at: "world-models#debate" },

  // ---- embodied (upgrade 2026-10-20)
  'robot-obs': { t: "观测（机器人）", en: "observation", d: "机器人在第 \\(t\\) 步能感知到的全部信息 \\(\\mathbf o_t\\)：多路相机图像、本体感知读数和语言指令。相当于强化学习里的状态，但只看得到世界的一部分。", at: "embodied#e0-task" },
  proprioception: { t: "本体感知", en: "proprioception", d: "机器人对自身的测量：各关节的角度、速度、力矩，夹爪的开度等。数据量很小（几个到几十个数），但每一步都有。", at: "embodied#e0-task" },
  'robot-action': { t: "动作（机器人）", en: "action", d: "每个控制步发给机器人的指令 \\(\\mathbf a_t\\)，如各关节的目标角度和夹爪开度，或末端的位移与旋转；由底层控制器负责让电机达到目标。", at: "embodied#e0-task" },
  'control-frequency': { t: "控制频率", en: "control frequency", d: "每秒发出多少个动作 \\(f\\)。灵巧操作通常几十赫兹（50 赫兹即每 20 毫秒一个动作），人形机器人的平衡控制几百赫兹。", at: "embodied#e0-task" },
  teleoperation: { t: "遥操作", en: "teleoperation", d: "人通过主手（同构的小机械臂、VR 手柄、数据手套）实时控制机器人完成任务，同时记录每一步的观测和动作，作为模仿学习的示范数据。", at: "embodied#e0-demo" },
  'end-effector': { t: "末端执行器", en: "end-effector", d: "机械臂末端直接与物体接触的部件，如夹爪、灵巧手。末端空间的动作给出它在三维空间中的位移和旋转，再由逆运动学换算成关节角。", at: "embodied#e0-space" },
  'multimodal-action': { t: "多峰动作分布", en: "multimodal action distribution", d: "同一个观测下正确的动作不止一种（从左绕或从右绕）。均方误差回归学到的是平均值 \\(\\mathbb E[\\mathbf a\\mid\\mathbf o]\\)，可能哪一种都不是；需要用 token 的 softmax 或扩散、流匹配来表示分布。", at: "embodied#bc" },
  'covariate-shift': { t: "协变量偏移", en: "covariate shift", d: "训练时的输入分布（专家走过的状态）与部署时的输入分布（策略自己走到的状态）不同。模仿学习中，小误差把机器人带到没见过的状态，误差因此越滚越大；它是暴露偏差在连续控制中的形式。", at: "embodied#bc" },
  dagger: { t: "DAgger", en: "Dataset Aggregation", d: "让当前策略自己执行，请专家为它实际到达的状态标注正确动作，并入数据集再训练，反复多轮（Ross 等, 2011）。把模仿学习的误差上界从 \\(T^2\\varepsilon\\) 降到 \\(uT\\varepsilon\\)，前提是错误可挽回。", at: "embodied#drift" },
  'action-chunk': { t: "动作块", en: "action chunk", d: "策略看一次观测，输出接下来一段（如 50 步）的动作再执行。决策次数从 \\(T\\) 降到 \\(T/k\\)，减轻误差累积；代价是两次决策之间无法对变化做出反应（ACT, 2023；π0 一次预测 50 步、执行 25 步）。", at: "embodied#chunk" },
  'fast-tokenizer': { t: "FAST 动作分词", en: "Frequency-space Action Sequence Tokenization", d: "把动作块逐维做离散余弦变换，系数缩放取整（小系数变 0），按先低频后高频排列，再用 BPE 压成 token（Physical Intelligence, 2025）。叠衬衫任务里 700 个分箱 token 压到 53 个。", at: "embodied#fast" },
  dct: { t: "离散余弦变换（DCT）", en: "discrete cosine transform", d: "把 \\(H\\) 个采样点写成 \\(H\\) 个不同频率余弦之和的正交变换，\\(C_j\\propto\\sum_n x_n\\cos[\\frac{\\pi}{H}(n+\\frac12)j]\\)。平滑信号的能量集中在前几个低频系数；JPEG 和 FAST 都靠它压缩。", at: "embodied#fast" },
  'action-expert': { t: "动作专家", en: "action expert", d: "接在视觉语言模型旁边、专门生成连续动作的较小网络（π0 中 3 亿参数），读取骨干各层的表示，用流匹配从噪声生成整个动作块。", at: "embodied#flow" },
  'dual-system': { t: "双系统（系统 1 / 系统 2）", en: "dual-system architecture", d: "大模型以几赫兹理解场景和指令（系统 2），小网络以上百赫兹把它的输出变成动作（系统 1），两者异步运行。Figure Helix（7–9 赫兹 / 200 赫兹）、GR00T N1（10 / 120 赫兹）采用。", at: "embodied#dual" },
  'sim-to-real': { t: "仿真到现实的差距", en: "sim-to-real gap", d: "仿真中的摩擦、质量、电机响应、延迟、视觉外观与真实世界的偏差，使仿真里学好的策略到真机上失效。", at: "embodied#sim" },
  'domain-randomization': { t: "域随机化", en: "domain randomization", d: "训练时每一局随机抽取物理和外观参数 \\(\\xi\\)，优化 \\(\\mathbb E_{\\xi}[J(\\pi;\\xi)]\\)，让真实世界只是又一个随机世界（Tobin 等, 2017；OpenAI 的 ADR, 2019）。范围越宽越稳健，也越保守。", at: "embodied#sim" },
  'advantage-conditioning': { t: "优势条件化", en: "advantage conditioning", d: "用价值函数给数据里的动作标上“好 / 不好”，训练以该标签为输入的策略，推理时固定输入“好”。由贝叶斯公式，它等于按“被标为好的概率”给原策略重新加权（π*0.6 的 Recap, 2025）。", at: "embodied#rlft" },

  // ---- on-device (upgrade 2026-10-20)
  'bw-utilization': { t: "带宽利用率", en: "bandwidth utilization", d: "实际用到的内存带宽与规格带宽之比 \\(\\eta\\)。单用户解码时生成速度 ≈ \\(\\eta\\cdot\\)带宽 ÷ 每 token 要读的字节；llama.cpp 跑分里显卡多在 65–85%，Mac 在 40–85%。", at: "on-device#od0-speed" },
  'expert-offload': { t: "专家卸载", en: "expert offloading", d: "MoE 放不进显存时，把专家权重放在 CPU 内存（或硬盘）里，注意力、KV 留在显卡上。生成时由 CPU 就地计算专家；每个 token 的时间是各层存储时间之和，由最慢的那一层决定。", at: "on-device#moe-local" },
  mmap: { t: "内存映射", en: "memory mapping (mmap)", d: "把文件直接映射成一段内存地址，用到哪一页才由操作系统从硬盘读入，内存紧张时再丢掉不常用的页。llama.cpp 默认这样加载模型，所以模型比内存大也能跑，但速度由硬盘决定。", at: "on-device#moe-local" },
  ple: { t: "逐层嵌入", en: "per-layer embeddings (PLE)", d: "Gemma 3n / Gemma 4 端侧版本的设计：每一层有自己的嵌入表，按 token 编号查表、不参与矩阵乘法，可以放在闪存或 CPU 内存里按需读取；常驻加速器内存的只有“有效参数”（E2B、E4B 中的 E）。", at: "on-device#phone" },
  'thermal-throttling': { t: "热降频", en: "thermal throttling", d: "芯片温度接近上限时，系统主动降低频率和电压以减少发热。手机长时间运行时的速度 ≈ 能持续散掉的功率 ÷ 每个 token 的能量，常只有峰值的五六成。", at: "on-device#phone-heat" },
  dvfs: { t: "动态调频调压", en: "dynamic voltage and frequency scaling (DVFS)", d: "同时调低频率和电压来省电。动态功耗 \\(\\propto CV^2f\\)，电压大致随频率变化时功耗 \\(\\propto f^3\\)；计算受限的任务降频时掉速少，访存为主的解码掉得多。", at: "on-device#phone-heat" },
  tops: { t: "TOPS", en: "tera operations per second", d: "每秒万亿次运算，NPU 的常用宣传指标，通常指 INT8，且常按 2:4 稀疏标注（稠密约为一半）。大模型解码受内存带宽限制，TOPS 与生成速度关系不大。", at: "on-device#embedded" },
  'device-cloud': { t: "端云协同", en: "device–cloud collaboration", d: "本地小模型处理简单、隐私敏感或离线的请求，必要时把复杂请求转给云端大模型。手机厂商的主流方案。", at: "on-device#cases" },

  // ---- spatial (upgrade 2026-10-20)
  'pinhole-camera': { t: "针孔相机模型", en: "pinhole camera model", d: "所有光线都穿过一个点（光心）落到成像平面上。相机坐标里的点 \\((X, Y, Z)\\) 落在像素 \\((fX/Z + c_x,\\ fY/Z + c_y)\\)：越远越靠近画面中心、越小。", at: "spatial#zero-pinhole" },
  'camera-intrinsics': { t: "内参", en: "camera intrinsics", d: "只和相机本身有关的参数：以像素计的焦距 \\(f\\) 和画面中心 \\((c_x, c_y)\\)，写成矩阵 \\(K\\)。", at: "spatial#zero-pinhole" },
  'camera-extrinsics': { t: "外参（相机位姿）", en: "camera extrinsics / pose", d: "相机放在哪、朝哪看：旋转 \\(R\\) 和平移 \\(\\mathbf t\\)，把世界坐标变成相机坐标 \\(\\mathbf X_c = R\\mathbf X_w + \\mathbf t\\)；光心位置是 \\(-R^\\top\\mathbf t\\)。", at: "spatial#zero-pinhole" },
  'pixel-ray': { t: "相机光线", en: "camera ray", d: "投影到同一个像素的所有三维点组成的射线 \\(\\mathbf r(s) = \\mathbf o + s\\,R^\\top K^{-1}(u, v, 1)^\\top\\)。渲染一张图就是对每条光线问“看到什么颜色”。", at: "spatial#zero-ray" },
  transmittance: { t: "透过率", en: "transmittance", d: "光沿光线走到第 \\(i\\) 层时还剩下的比例 \\(T_i = \\prod_{j<i}(1-\\alpha_j)\\)；在连续介质里是 \\(\\exp(-\\int\\sigma\\,ds)\\)。", at: "spatial#zero-composite" },
  'alpha-compositing': { t: "alpha 合成", en: "alpha compositing", d: "按从近到远的顺序叠加半透明层：\\(C = \\sum_i T_i\\alpha_i\\mathbf c_i + T_{N+1}\\mathbf c_{\\text{bg}}\\)（Porter 与 Duff, 1984）。NeRF 与高斯泼溅渲染像素都用它。", at: "spatial#zero-composite" },
  'differentiable-rendering': { t: "可微渲染", en: "differentiable rendering", d: "渲染结果对场景参数可以求导，于是能用“渲染图 vs 照片”的误差做梯度下降，从照片反推三维。", at: "spatial#zero-inverse" },
  sfm: { t: "运动恢复结构（SfM）", en: "structure from motion", d: "从一组照片同时求出每张照片的相机位姿和场景的稀疏三维点：特征匹配 → 三角化 → 光束法平差。COLMAP（2016）是标准工具。", at: "spatial#sfm" },
  triangulation: { t: "三角化", en: "triangulation", d: "从两台已知相机各引一条光线，交点就是三维位置。平移 \\(B\\)、焦距 \\(f\\)、视差 \\(d\\) 时，深度 \\(Z = fB/d\\)。", at: "spatial#sfm" },
  'bundle-adjustment': { t: "光束法平差", en: "bundle adjustment", d: "同时调整所有相机和三维点，使每个点投影回每张照片时与实际观察到的位置之差（重投影误差）的平方和最小。", at: "spatial#sfm" },
  mvs: { t: "多视图立体（MVS）", en: "multi-view stereo", d: "在 SfM 给出的相机上逐像素匹配、估计深度，得到稠密点云或网格；依赖纹理，白墙、反光、半透明处容易失败。", at: "spatial#sfm" },
  'spectral-bias': { t: "频谱偏置", en: "spectral bias", d: "梯度下降训练的 MLP 先学低频、后学高频；数据在圆周上时，频率 \\(k\\) 的分量约需 \\(k^2\\) 倍的时间（神经正切核的特征值随频率衰减）。", at: "spatial#nerf-pe" },
  'fourier-features': { t: "傅里叶特征（NeRF 的位置编码）", en: "Fourier features", d: "把坐标映射成 \\(\\sin(2^k\\pi p), \\cos(2^k\\pi p)\\)，\\(k = 0..L-1\\)，让 MLP 学得动高频细节；频率上限要和数据能支撑的细节匹配。", at: "spatial#nerf-pe" },
  'hash-encoding': { t: "多分辨率哈希编码", en: "multiresolution hash encoding", d: "把空间切成 16 种粗细的网格，格点哈希到可训练的特征表，插值后拼接交给小 MLP；容量从网络搬进表里（Instant-NGP, 2022）。", at: "spatial#nerf-ngp" },
  'spherical-harmonics': { t: "球谐函数", en: "spherical harmonics", d: "球面上的傅里叶基函数，用来表示“从不同方向看是什么颜色”。3DGS 取到 3 阶，每个颜色通道 16 个系数。", at: "spatial#gs" },
  'tile-rasterization': { t: "分块光栅化", en: "tile-based rasterization", d: "把屏幕切成 16×16 像素的小块，高斯按“小块编号 + 深度”全局排序，每块从近到远合成、透过率很低时提前停止；3DGS 实时渲染的关键。", at: "spatial#gs" },
  densification: { t: "自适应密度控制", en: "adaptive density control", d: "3DGS 训练中按位置梯度增删高斯：小的复制、大的拆分、几乎透明的删除，数量从 SfM 的几万个长到几百万个。", at: "spatial#gs" },
  'janus-problem': { t: "雅努斯问题", en: "Janus problem", d: "用 SDS 生成的三维物体从每个角度看都长出一张正脸：每个视角各自被推向二维模型的众数，而二维模型不知道视角。", at: "spatial#gen" },
  'multiview-diffusion': { t: "多视角扩散模型", en: "multi-view diffusion model", d: "同时生成同一物体多个视角的扩散模型，各视角一起去噪、彼此一致（MVDream, 2023），用来缓解雅努斯问题或给前馈重建提供输入。", at: "spatial#gen" },
  lrm: { t: "大型重建模型（LRM）", en: "large reconstruction model", d: "一个 Transformer 读入一张或几张图，直接输出 NeRF 或高斯泼溅（LRM, 2023-11：5 亿参数、约 5 秒）；看不见的部分靠回归，常偏模糊。", at: 'spatial#ff-gen' },
  pointmap: { t: "点图", en: "pointmap", d: "每个像素对应一个三维坐标、都表示在同一台相机坐标系里的图（DUSt3R）。从中可以解出深度、焦距和相对位姿，取代特征匹配与三角化。", at: 'spatial#ff-geo' },
  'structured-latent': { t: "结构化三维潜空间", en: "structured 3D latent", d: "只在物体表面附近的稀疏体素上放潜向量的三维潜空间；先生成哪些体素有东西，再生成潜向量，可解码成辐射场、高斯泼溅或网格（TRELLIS）。", at: 'spatial#ff-gen' },
  'cognitive-map': { t: "认知地图", en: "cognitive map", d: "把看到的东西放进一张统一的空间平面图的内部表示。VSI-Bench 发现多模态模型的空间推理瓶颈主要在这里，显式画出它能提高距离题成绩。", at: "spatial#reasoning" },

  // ---- generation (upgrade 2026-10-20)
  surprisal: { t: "信息量（惊讶度）", en: "surprisal / self-information", d: "概率为 \\(p\\) 的结果发生时带来的 \\(-\\log_2 p\\) 比特：概率 1/2 是 1 比特，1/8 是 3 比特。熵是它的平均值，交叉熵是真实数据在模型下的平均信息量。", at: "generation#g0-info" },
  'arithmetic-coding': { t: "算术编码", en: "arithmetic coding", d: "按模型给的概率逐个切分区间 [0, 1)，最后区间宽度等于整段文本的概率 \\(p\\)，约需 \\(-\\log_2 p + 2\\) 比特。它把“预测得准”直接变成“压得短”。", at: "generation#ppl" },
  backoff: { t: "回退与平滑", en: "backoff and smoothing", d: "n-gram 处理没见过的上下文的办法：退回更短的上下文，并从见过的事件里匀出一点概率给没见过的，避免概率为 0（如 Kneser-Ney）。", at: "generation#ngram" },
  'neural-lm': { t: "神经语言模型", en: "neural language model", d: "用神经网络代替计数来估计下一个词的分布：先把词变成向量，再从上下文向量算出 softmax（Bengio 等, 2003）。相似的上下文因此共享统计。", at: "generation#ngram" },
  'typical-set': { t: "典型集", en: "typical set", d: "每个 token 的平均信息量接近熵 \\(H\\) 的那些序列。几乎所有样本都落在其中；概率最高的单条序列反而不在其中，这是贪心和束搜索文本“空洞”的信息论解释。", at: "generation#degen" },
  degeneration: { t: "文本退化", en: "neural text degeneration", d: "用贪心或束搜索做开放式生成时，文本变得空洞、重复、陷入循环的现象（Holtzman 等, 2019）。采样加截断是主要对策。", at: "generation#degen" },
  'repetition-penalty': { t: "重复惩罚", en: "repetition / frequency / presence penalty", d: "按 token 在已生成文本中出现的次数压低它的 logit：\\(z_i - \\alpha_{\\text{freq}}c_i - \\alpha_{\\text{pres}}\\mathbb 1[c_i>0]\\)。能打断循环，也会误伤本该重复的词。", at: "generation#degen" },
  'block-diffusion': { t: "块扩散", en: "block diffusion (semi-autoregressive)", d: "把序列切成块，块与块之间从左到右生成，块内部用扩散并行填写；块长为 1 即自回归，等于全文即纯扩散。", at: "generation#dlm" },

  // ---- attention (upgrade 2026-10-20)
  'path-length': { t: "路径长度", en: "path length", d: "两个位置之间，信号（以及反向传播的梯度）要经过的计算步数。RNN 里等于两个位置的距离 \\(O(n)\\)，每一步都要乘一个雅可比矩阵；自注意力里任意两个位置之间只隔一步 \\(O(1)\\)。", at: "attention#before" },
  'attn-score': { t: "注意力分数", en: "attention score (attention logit)", d: "softmax 之前的那个数：\\(s_{ij} = \\mathbf q_i\\cdot\\mathbf k_j/\\sqrt{d_h}\\)。softmax 之后变成注意力权重 \\(a_{ij}\\)。“分数失控”指训练中它越变越大，使 softmax 饱和。", at: "attention#zero-score" },
  'qk-circuit': { t: "QK 电路", en: "QK circuit", d: "一个注意力头里决定“看哪里”的部分：\\(W_{QK} = W_QW_K^\\top\\)，分数 \\(\\mathbf x_iW_{QK}\\mathbf x_j^\\top\\) 是两个 token 向量的低秩双线性函数，秩不超过 \\(d_h\\)。", at: 'attention#zero-big' },
  'ov-circuit': { t: "OV 电路", en: "OV circuit", d: "一个注意力头里决定“搬什么、写到哪”的部分：\\(W_{OV} = W_VW_O\\)。被看到的位置的向量乘上它，加回当前位置。可解释性研究常把一个头拆成 QK 和 OV 两部分分析。", at: 'attention#zero-big' },
  'softmax-saturation': { t: "softmax 饱和", en: "softmax saturation", d: "分数彼此拉得太开时，softmax 几乎只剩最大的一项（接近独热）。此时雅可比 \\(a_i(\\delta_{ij}-a_j)\\) 接近零，梯度传不回分数。注意力除以 \\(\\sqrt{d_h}\\)、QK-Norm 都是为了避免它。", at: "attention#scale" },
  'qk-clip': { t: "QK-Clip", en: "QK-Clip", d: "Kimi K2（2025）的做法：不改前向计算，每步更新后检查每个头的最大注意力分数，超过阈值 \\(\\tau\\)（K2 取 100）就把这个头的 \\(W_Q, W_K\\) 按比例缩小。与 Muon 合起来叫 MuonClip。", at: "attention#scale" },
  'prev-token-head': { t: "前一个 token 头", en: "previous-token head", d: "几乎把全部权重放在紧挨着的前一个位置上的注意力头，靠位置编码实现。它把“我前面是谁”写进每个位置，是归纳头的前置零件。", at: 'attention#induction' },
  'additive-attention': { t: "加性注意力", en: "additive attention (Bahdanau attention)", d: "Bahdanau 等（2014）的打分方式：\\(\\mathbf w^\\top\\tanh(W_1\\mathbf s + W_2\\mathbf h)\\)，用一个小网络比较解码器状态和编码器某个位置的隐藏状态。每对位置都要单独算一次，不能写成一次矩阵乘法，后来被点积打分取代。", at: "attention#evolution" },
  'sparse-attention': { t: "稀疏注意力", en: "sparse attention", d: "每个 query 只看挑出来的一部分位置，而不是全部。早期用固定模式（Sparse Transformer, 2019：局部 + 跨步，\\(O(n\\sqrt n)\\)），2025 年后改成按内容挑选（NSA、DeepSeek 的 DSA）。", at: "attention#evolution" },
  mqa: { t: "MQA", en: "multi-query attention", d: "多查询注意力（Shazeer, 2019）：所有 query 头共用同一组 K、V，KV 缓存和每步读取量都除以头数 \\(h\\)。质量和训练稳定性有损，后来被折中的 GQA 取代。", at: 'attention#zero-big' },

  // ---- transformer (upgrade 2026-10-20)
  'hidden-dim': { t: "隐藏维度", en: "hidden dimension (model width)", d: "每个位置上残差流向量的维数，记作 \\(d\\)。Llama 3 8B 是 4096；注意力、MLP 的输入输出都是 \\(d\\) 维，每层参数约 \\(12d^2\\)。", at: "transformer#zero" },
  'post-norm': { t: "Post-Norm", en: "post-normalization", d: "原版 Transformer 的做法：先相加再归一化，\\(\\mathbf x_{l+1} = \\operatorname{Norm}(\\mathbf x_l + F(\\mathbf x_l))\\)。残差流每层都被重新缩放，没有恒等的直通路径，深了难训、需要学习率预热。", at: "transformer#norm" },
  'lr-warmup': { t: "学习率预热", en: "learning-rate warmup", d: "训练开头的几百到几千步里，把学习率从接近 0 逐步升到目标值。Post-Norm 的 Transformer 离不开它；Pre-Norm 可以省掉，但实践中大多保留一段较短的预热。", at: "transformer#norm" },
  'prenorm-dilution': { t: "PreNorm 稀释", en: "PreNorm dilution", d: "Pre-Norm 结构中，残差流长度随层数约按 \\(\\sqrt l\\) 增长，而每层写入的大小大致固定，越深的层写入的内容占比越小、影响越弱。Attention Residuals 论文的叫法。", at: "transformer#norm" },
  'sinusoidal-pe': { t: "正弦位置编码", en: "sinusoidal positional encoding", d: "原版 Transformer 的位置编码：位置 \\(m\\) 的向量各维为 \\(\\sin(m\\omega_i)\\)、\\(\\cos(m\\omega_i)\\)，\\(\\omega_i = 10000^{-2i/d}\\)，直接加到嵌入上。平移等于旋转，但相加后绝对位置会混进注意力分数。", at: "transformer#position" },
  'relative-pos-bias': { t: "相对位置偏置", en: "relative position bias", d: "不改向量，直接给注意力分数加一个只依赖距离的偏置。T5（2019）每个头按距离分 32 个桶查表；ALiBi（2021）取 \\(-c_h|m-n|\\)。", at: "transformer#position" },
  'pos-interp': { t: "位置插值", en: "position interpolation (PI)", d: "扩展 RoPE 上下文的方法：把位置按比例压缩，\\(m\\to m\\cdot n_{\\text{train}}/n_{\\text{test}}\\)，让旋转角度都落回训练时见过的范围；代价是相邻位置更难分辨。", at: "transformer#position" },
  yarn: { t: "YaRN", en: "Yet another RoPE extensioN", d: "2023 年的 RoPE 上下文扩展方法：只压缩低频平面、保留高频平面，并对注意力分数做温度修正，少量长文本微调即可把上下文扩大数倍到数十倍。", at: "transformer#position" },
  nope: { t: "NoPE", en: "no positional encoding", d: "完全不用位置编码的注意力层。带因果掩码时模型能从“能看到几个 token”推出位置；Llama 4、SmolLM3 等每隔几层放一个，Kimi Linear 的全注意力层全部不用。", at: "transformer#position" },
  'qk-norm': { t: "QK-Norm", en: "query-key normalization", d: "点积之前给 q、k 各做一次归一化（按头），\\(s = \\operatorname{Norm}(\\mathbf q)\\cdot\\operatorname{Norm}(\\mathbf k)/\\sqrt{d_h}\\)，把注意力分数锁在有界范围内，防止训练中分数失控。Gemma 3、Qwen3、OLMo 2 等采用。", at: "attention#scale" },
  'gated-attention': { t: "门控注意力", en: "gated attention", d: "在注意力的加权和上（乘 \\(W_O\\) 之前）逐头逐维乘一个由当前 token 决定的 sigmoid 门：\\(\\mathbf o_i' = \\sigma(\\mathbf x_iW_g)\\odot\\mathbf o_i\\)。Qwen 团队 2025 年提出，去掉了注意力汇和巨量激活，训练更稳；用于 Qwen3-Next。", at: 'attention#sink' },
  mhc: { t: "mHC", en: "manifold-constrained hyper-connections", d: "流形约束超连接（DeepSeek, 2025-12）：把残差流扩成 n 条并行的流，用被约束为双随机矩阵的可学习矩阵混合，信号放大被限制在约 1.6 倍。用于 DeepSeek V4。", at: "transformer#residual-2026" },
  'attn-res': { t: "Attention Residuals", en: "Attention Residuals (AttnRes)", d: "Kimi 2026 年提出的残差连接：每层用学到的查询向量，对之前各层（或各块）的输出做 softmax 注意力，取代等权相加 \\(\\mathbf x_0 + \\sum_l F_l\\)，缓解 PreNorm 稀释。用于 Kimi K3。", at: "transformer#residual-2026" },
  'massive-activations': { t: '巨量激活', en: 'massive activations', d: '大模型里极少数比其它大几个数量级（可达十万倍）的激活值，几乎不随输入变化，作用像固定偏置；常与注意力汇同时出现，给量化带来麻烦（Sun 等, 2024）。', at: 'attention#sink' },

  // ---- tokens (upgrade 2026-10-20)
  tokenizer: { t: "分词器", en: "tokenizer", d: "把文本切成 token 并换成编号、以及把编号拼回文字的程序。在训练模型之前单独训练好，之后固定不变。", at: "tokens#why" },
  'pre-tokenization': { t: "预分词", en: "pre-tokenization", d: "合并之前先用规则（通常是正则表达式）把文本切成词块，合并只在块内进行：英文单词连同前面的空格一块、标点一块、数字按规则成块。", at: "tokens#bpe" },
  'code-point': { t: "码点", en: "Unicode code point", d: "Unicode 给每个字符的编号，如“a”是 U+0061、“模”是 U+6A21。存储时再按 UTF-8 等编码成 1–4 个字节。", at: "tokens#bytes" },
  'byte-fallback': { t: "字节回退", en: "byte fallback", d: "以字符和子词为主的词表外加 256 个字节 token；遇到词表里没有的字符，就退回它的 UTF-8 字节，因此不会出现 [UNK]（LLaMA、Gemma 等）。", at: "tokens#bytes" },
  'em-algorithm': { t: "EM 算法", en: "expectation–maximization", d: "数据里有看不见的部分时估计参数的方法：E 步按当前参数算出隐藏部分的后验，M 步用期望次数重新估参数；每一轮似然不下降。Unigram 分词用它估计 token 概率。", at: "tokens#unigram" },
  'token-premium': { t: "分词溢价", en: "tokenization premium", d: "同一段内容在某种语言下切出的 token 数，除以英文版的 token 数。等于字符数之比乘以 fertility 之比，取决于分词器的训练数据，而不是语言本身。", at: "tokens#lang" },
  'glitch-token': { t: "故障 token", en: "glitch token", d: "词表里有、但模型训练时几乎没见过的 token（如 “SolidGoldMagikarp”）。它的嵌入几乎没被更新，模型遇到它会胡言乱语或拒绝复述。", at: 'tokens#embed' },
  word2vec: { t: "word2vec", en: "word2vec", d: "2013 年的词向量方法：训练一个小网络用每个词预测它周围的词（skip-gram），把词压成几百维的稠密向量；意思相近的词向量相近。", at: "tokens#meaning" },
  'neg-sampling': { t: "负采样", en: "negative sampling", d: "用“真邻居判为是、随机抽的 \\(k\\) 个假邻居判为否”的二分类代替对整个词表的 softmax；最优解满足点积 = PMI − \\(\\log k\\)。", at: "tokens#meaning" },
  'lm-head': { t: "输出矩阵（LM head）", en: "LM head / unembedding", d: "模型最后一层的 \\(V\\times d\\) 矩阵 \\(W_U\\)，把最终向量变成词表里每个 token 的分数（logit）。每个 token 的计算量约 \\(2Vd\\)；共享嵌入时 \\(W = E\\)。", at: "tokens#output" },
  superword: { t: "超词", en: "superword token", d: "跨越多个词（含空格）的 token，如 “by the way”。SuperBPE 在训练后期放开“不能跨空格”的预分词规则来学习它们。", at: "tokens#frontier" },
  'ngram-embedding': { t: "n-gram 嵌入", en: "n-gram embedding", d: "给相邻几个 token 的组合也配一个向量，用哈希映射到一张大表里，与单个 token 的嵌入相加。只放大输入端，几乎不增加算力（Over-Tokenized Transformer、Engram）。", at: "tokens#frontier" },
  'entropy-patching': { t: "按熵分组", en: "entropy patching", d: "字节级模型的分组方法：用一个小语言模型估计下一个字节的熵，超过阈值就开一个新组；好猜处组长、难猜处组短（BLT）。", at: "tokens#frontier" },

  // ---- scaling (upgrade 2026-10-20)
  'compute-optimal': { t: "训练算力最优", en: "compute-optimal", d: "给定训练算力 \\(C\\approx 6ND\\) 时让损失最低的那组参数量和数据量。Chinchilla 的结论是两者同比例增长，约每参数 20 token；最优点附近很平。", at: "scaling#z-budget" },
  isoflop: { t: "等算力曲线", en: "IsoFLOP curve", d: "固定一个训练算力预算，训练一串大小不同的模型，画出损失对参数量的曲线；最低点就是这笔算力的最优模型大小。Chinchilla 的第二种方法。", at: "scaling#chinchilla" },
  'data-constrained': { t: "数据受限的规模定律", en: "data-constrained scaling law", d: "Muennighoff 等（2023）：不重复数据只有 \\(U\\) 时，把 Chinchilla 式里的 \\(N\\)、\\(D\\) 换成打折后的有效值。重复约 4 遍几乎等于新数据，有效数据最多约 16 倍；多余参数贬值更快，所以算力应主要加在遍数上。", at: "scaling#repeat" },
  'exact-match': { t: "精确匹配", en: "exact match", d: "答案必须一字不差才算对的评分方式。逐位正确率 \\(p\\) 平滑上升时，\\(k\\) 位答案的得分 \\(p^k\\) 看起来像突变，是很多“涌现”的来源。", at: "scaling#emergence" },
  'lr-schedule': { t: "学习率调度", en: "learning-rate schedule", d: "学习率随训练步数的变化方式。常见的是预热后按余弦降到接近 0，或 WSD（长时间恒定、最后快速衰减）。", at: "scaling#schedule" },
  'noise-floor': { t: "噪声地板", en: "noise floor (SGD)", d: "随机梯度有噪声，学习率不为 0 时参数在谷底附近抖动，带来约 \\(\\eta\\sigma^2/4\\) 的额外损失（\\(\\sigma^2\\) 为梯度噪声方差）。降低学习率可以迅速消掉它，这是衰减段损失骤降的原因。", at: "scaling#schedule" },
  mup: { t: "μP", en: "maximal update parametrization (μP)", d: "按宽度缩放各层的初始化、学习率和输出乘子（对 Adam：隐藏层学习率 \\(\\propto 1/d\\)），使每步更新对各层输出的影响与宽度无关，小模型上调好的超参数可以直接用于大模型。", at: "scaling#mup" },
  'weight-decay': { t: "权重衰减", en: "weight decay", d: "每步把参数往 0 拉一点（乘以 \\(1-\\eta\\lambda_{\\text{wd}}\\)），防止参数无限增长。AdamW 把它从梯度里解耦出来、直接作用于参数；Moonlight 发现 Muon 在大规模训练中也需要它。", at: "scaling#optim" },
  'newton-schulz': { t: "牛顿-舒尔茨迭代", en: "Newton–Schulz iteration", d: "只用矩阵乘法、近似计算矩阵正交化 \\(UV^\\top\\) 的迭代：反复作用一个奇次多项式 \\(X\\leftarrow aX + b(XX^\\top)X + c(XX^\\top)^2X\\)，把所有奇异值推向 1。Muon 用 5 次。", at: "scaling#muon" },
  'spectral-norm': { t: "谱范数", en: "spectral norm", d: "矩阵的最大奇异值 \\(\\|W\\|_2\\)：它最多能把一个向量放大多少倍。限制更新的谱范数，等于限制一层的输出对任何输入最多变化多少；Muon 是谱范数下的最陡下降。", at: "scaling#muon" },

  // ---- sft (upgrade 2026-10-20)
  'loss-mask': { t: "损失掩码", en: "loss mask", d: "给序列的每个位置一个 0 或 1 的权重，决定它算不算进损失。SFT 通常提示为 0、回答为 1：提示照样输入模型，但不产生梯度。", at: "sft#z-mask" },
  'reference-model': { t: "参考模型", en: "reference model", d: "偏好优化和 RL 里冻结不动的出发点 \\(\\pi_{\\text{ref}}\\)，通常是 SFT 模型。用 KL 散度限制新模型不要离它太远。", at: "sft#z-kl" },
  'implicit-reward': { t: "隐式奖励", en: "implicit reward", d: "\\(\\beta\\log\\frac{\\pi_\\theta(y|x)}{\\pi_{\\text{ref}}(y|x)}\\)：模型相对参考模型把这个回答的对数概率提高了多少。DPO 把它当作奖励，放进 Bradley-Terry 损失。", at: "sft#z-dpo" },
  'annotator-agreement': { t: "标注者一致率", en: "inter-annotator agreement", d: "两位标注者独立比较同一对回答、选了同一个的比例。InstructGPT 约 73%；它给奖励模型能测到的准确率设了上限。", at: "sft#noise" },
  goodhart: { t: "古德哈特定律", en: "Goodhart's law", d: "“一个指标一旦成为目标，就不再是好指标。”对代理指标（奖励模型、点赞、测试）优化得越狠，它与真实目标的偏差越会被放大。", at: "sft#goodhart" },
  'best-of-n': { t: "best-of-n 采样", en: "best-of-n sampling", d: "对同一个提示采样 \\(n\\) 个回答，留下奖励模型打分最高的。离原模型的 KL 至多 \\(\\ln n - (n-1)/n\\)。把选出的回答再拿去做 SFT 叫拒绝采样微调。", at: "sft#goodhart" },
  overoptimization: { t: "奖励过度优化", en: "reward overoptimization", d: "对代理奖励模型优化过头：代理分数一路上涨，真实质量先升后降（Gao 等, 2022）。奖励模型越大、数据越多，峰值来得越晚。", at: "sft#goodhart" },
  'likelihood-displacement': { t: "似然位移", en: "likelihood displacement", d: "DPO 训练中好回答和差回答的概率常常一起下降、只是差回答降得更多，概率被挪给数据之外的回答（Razin 等, 2024）。", at: "sft#dpo" },
  'iterative-dpo': { t: "在线 / 迭代 DPO", en: "online / iterative DPO", d: "每隔一段时间（或每一步）用当前模型重新采样回答、请人或模型重新标注，再做 DPO，让偏好数据跟上模型的分布。", at: "sft#variants" },
  rlaif: { t: "RLAIF", en: "reinforcement learning from AI feedback", d: "用模型代替人做偏好比较，训练奖励模型或直接做偏好优化。与 RLHF 效果相当（Lee 等, 2023），今天大多数偏好数据由模型标注。", at: "sft#variants" },
  'constitutional-ai': { t: "宪法 AI", en: "Constitutional AI", d: "Anthropic（2022-12）：模型按一组成文原则批评、修改自己的回答做 SFT，再按原则比较回答、用 AI 标注做强化学习。RLAIF 的起点。", at: "sft#variants" },
  'intrinsic-dim': { t: "内在维度", en: "intrinsic dimension", d: "把微调限制在一个随机低维子空间里、仍能达到全参数微调 90% 效果所需的最小维数。RoBERTa 在 MRPC 上约 200；模型越大越低。", at: "sft#lora" },
  'linear-mode-connectivity': { t: "线性模式连通性", en: "linear mode connectivity", d: "两个模型之间沿直线插值权重，损失不会先升高再降低。从同一个预训练点出发的微调模型通常满足它，这是权重合并能成立的前提。", at: "sft#merge" },

  // ---- coding (upgrade 2026-10-20)
  'pull-request': { t: "拉取请求（PR）", en: "pull request", d: "把一个补丁提交给项目维护者审查、合并的请求。开源项目的修改大多以 PR 的形式进入仓库；SWE-bench 的题目就取自已合并的 PR。", at: "coding#c0-edit" },

  // ---- on-device (upgrade 2026-10-20)
  'kv-quant': { t: "KV 量化", en: "KV cache quantization", d: "把 KV 缓存里的 K、V 存成 8 位或 4 位，读出时再还原，用来在同样的内存里放下更长的上下文。K 有通道方向的离群值，比 V 难量化；Q8_0 基本无损，4 位在长上下文上有掉点报告。", at: "on-device#od0-kv" },

  // ---- image (upgrade 2026-10-20)
  'consistency-model': { t: "一致性模型", en: "consistency model", d: "学一个函数 \\(f_\\theta(\\mathbf x_t, t)\\approx\\mathbf x_0\\)，把概率流 ODE 轨迹上任何一点直接映射到终点。训练目标是自一致性：同一轨迹上相邻两点的输出相同，再把 \\(t\\to 0\\) 一端钉住；于是一步就能生成（Song 等, 2023；LCM 把它用到潜空间扩散）。", at: "image#fast" },

  // ---- spatial (upgrade 2026-10-20)
  'novel-view-synthesis': { t: "新视角合成", en: "novel view synthesis", d: "从没有拍过的相机位置渲染出照片。评测时留出几张照片不参与训练，训练后从这些位置重新渲染、和真照片比（PSNR 等），以此检验学到的是三维而不是背下了照片。", at: "spatial#zero-inverse" },
};
